/* @@incluir scripts/lib/xlsx_conferencia.js */
// Consolida config_execucao.json + cobrancas.json + apelidos.json + cost_reports.json (binário -> JSON)
// e embute os 3 perfis de projeto (cópia de /profiles/*.json — seção 6 do spec.md).
// Perfis embutidos aqui (não buscados via HTTP), por decisão já confirmada.

// Leitura de binário: esta instância do n8n guarda binário no disco (filesystem-v2),
// então item.binary.data.data NÃO é o conteúdo, e sim o rótulo do modo de armazenamento.
// O único acesso liberado no Code Node é helpers.getBinaryDataBuffer, que lê pelo ÍNDICE
// do item no input DIRETO — daí localizarmos o item pelo id do binário. Cobre os 2 modos.
const helpers = this.helpers;
const entradasDoNode = $input.all();
async function bufferDe(item, prop) {
  prop = prop || 'data';
  const b = item && item.binary && item.binary[prop];
  if (!b) return null;
  if (!b.id) return Buffer.from(b.data, 'base64'); // modo embutido
  const i = entradasDoNode.findIndex((e) => e.binary && e.binary[prop] && e.binary[prop].id === b.id);
  if (i < 0) throw new Error('binario "' + (b.fileName || prop) + '" nao esta no input direto deste node — o Code Node so consegue le-lo por ai');
  return await helpers.getBinaryDataBuffer(i, prop);
}

async function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return {};
  const buffer = await bufferDe(item);
  return JSON.parse(buffer.toString('utf8'));
}

const config = await parseBinaryJson($('Ler config_execucao.json').first());
const cobrancas = await parseBinaryJson($('Ler cobrancas.json').first());
const apelidos = await parseBinaryJson($('Ler apelidos.json').first());
const costs = await parseBinaryJson($('Ler cost_reports.json').first());

// Config dos Cost (C.1, D4(a)). A versão esperada é a do config/cost_reports*.json do repositório:
// o teste tests/fase1_ciclo_cost.teste.js para se esta constante e o arquivo divergirem. Se a cópia
// da VM for de outra versão, PARA aqui, antes de qualquer leitura ou escrita.
const VERSAO_COST_REPORTS = '2026-10-29.2';
if (!costs || !costs.versao) {
  throw new Error('PAROU: cost_reports__SUFIXO_AMBIENTE__.json ausente ou vazio em /home/node/.n8n-files/box-fish-config/ (no host, /opt/box-fish-config/). Copie do repositório (passo 4 do C.8).');
}
if (costs.versao !== VERSAO_COST_REPORTS) {
  throw new Error('PAROU: a config da VM não é a do repositório (cost_reports versao "' + costs.versao + '", esperada "' + VERSAO_COST_REPORTS + '").');
}
// Chamado no return, DEPOIS de o ambiente deste arquivo ser fixado (marca "[gerado]" do gerador).
function costsConferidos(ambiente) {
  if (costs.ambiente !== ambiente) throw new Error('PAROU: o cost_reports lido é de "' + costs.ambiente + '", e este workflow é "' + ambiente + '".');
  const problemas = validarConfig(costs);
  if (problemas.length) throw new Error('PAROU: config dos Cost com problema (' + problemas.join('; ') + '). Nada foi lido nem escrito.');
  return costs;
}

const perfis = {
  AREP: {
    projeto: 'AREP (S01 antigo)',
    prefixo_assunto_pedido: 'AREP | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'AREP | NOTAS À PAGAR',
    texto_ref: 'SMTC',
    retranca: 'S01',
  },
  REUNION: {
    projeto: 'Reunion (S01)',
    prefixo_assunto_pedido: 'SMTC - S01 | REUNION | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'SMTC - S01 | REUNION | NOTAS À PAGAR',
    texto_ref: 'SMTC - REUNION',
    retranca: 'REUNION_S01',
  },
  SOFT_PRE: {
    projeto: 'Soft Pré (S02)',
    prefixo_assunto_pedido: 'SMTC - S02 | SOFT PRE | EMISSÃO DE NF',
    prefixo_assunto_entrega: 'SMTC - S02 | SOFT PRE | NOTAS À PAGAR',
    texto_ref: 'SMTC - SOFT PRE',
    retranca: 'SOFT PRE_S02',
  },
};

return [{ json: { config, cobrancas, apelidos, perfis, dominioEmpresa: 'novorealitybox.com', costs: costsConferidos(config.ambiente) } }];

// Requer NODE_FUNCTION_ALLOW_EXTERNAL=exceljs,xlsx configurado na VM (spec.md 5 e 7.5).
// Duas bibliotecas de propósito, cada uma pelo que a outra não faz:
//   exceljs  -> Cost Report (.xlsx). É a única que expõe a COR de preenchimento da célula,
//               que é o que separa AREP de REUNION (spec 6).
//   SheetJS  -> Contratos (.xlsb). O exceljs não lê .xlsb — e pior, falha calado: abre o
//               arquivo e devolve zero abas, o que faria todo mundo virar "sem contrato".
// Os 4 arquivos chegam pelo "Merge — downloads + config", que tem a MESMA forma nos dois
// ambientes: input 0 = config (sem binário), 1 = Cost Report DA FONTE DESTA PASSADA (já passou
// pelo portão, C.6), 2/3/4 = Contratos AREP / Reunion / Soft Pré.
//
// Identificamos por POSIÇÃO, de propósito, e não por nome de node (o Merge é o input direto, e
// o binário só se lê pelo input direto).
//
// A leitura em si usa helpers.getBinaryDataBuffer porque esta instância guarda binário no
// disco (filesystem-v2): ali binary.data.data é o rótulo do modo, não o conteúdo.
const helpers = this.helpers;
const entradasDoNode = $input.all();
const posicoesComBinario = [];
entradasDoNode.forEach((it, i) => { if (it.binary && it.binary.data) posicoesComBinario.push(i); });
if (posicoesComBinario.length !== 4) {
  throw new Error(
    'esperava 4 arquivos no input (o Cost Report da passada + 3 planilhas de Contratos), vieram ' +
    posicoesComBinario.length + '. Confira as ligações do "Merge — downloads + config".'
  );
}
async function bufferNaPosicao(pos) {
  const i = posicoesComBinario[pos];
  const b = entradasDoNode[i].binary.data;
  if (!b.id) return Buffer.from(b.data, 'base64'); // modo embutido
  return await helpers.getBinaryDataBuffer(i, 'data');
}

const ExcelJS = require('exceljs');
const XLSX = require('xlsx');

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

// .text estoura com "Cannot read properties of null (reading 'toString')" quando a célula
// não tem valor — acontece de verdade nesta planilha, em células mescladas (ValueType 1).
// Esta versão do exceljs não protege esse caso.
function textoDaCelula(row, col) {
  try {
    const c = row.getCell(col);
    if (!c || c.value === null || c.value === undefined) return '';
    return c.text;
  } catch (e) {
    return '';
  }
}

// Mantém a semântica do original (Number(cell.value) || 0), só que sem estourar em célula
// vazia/mesclada e resolvendo célula de fórmula pelo resultado calculado.
function numeroDaCelula(row, col) {
  try {
    const c = row.getCell(col);
    const v = c && c.value;
    if (v && typeof v === 'object' && 'result' in v) return Number(v.result) || 0;
    return Number(v) || 0;
  } catch (e) {
    return 0;
  }
}

// getWorksheet() do exceljs é sensível a maiúsculas, e a aba real chama-se "NOTAS".
// O código antigo caía num fallback silencioso pro worksheets[0] e lia a aba errada
// ("DETALHADO MÃE"), sem nenhum sinal de erro.
function abaChamada(wb, nome) {
  const alvo = String(nome).trim().toUpperCase();
  return wb.worksheets.find((w) => String(w.name).trim().toUpperCase() === alvo) || null;
}

// Identificacao de projeto no S01 pela COR DE PREENCHIMENTO da linha (spec secoes 5 e 6):
// Reunion = roxo/cinza-arroxeado; AREP = sem preenchimento.
//
// DOIS bugs corrigidos aqui, ambos confirmados contra a planilha real:
//
// 1. A versao antiga so olhava fill.fgColor.argb. Esta planilha usa COR DE TEMA
//    (fgColor.theme + tint), onde argb e undefined — entao a funcao devolvia false pra
//    TODAS as 3.537 linhas e todo mundo virava AREP, inclusive linhas com "REUNION" na
//    propria descricao.
// 2. A cor era lida da coluna L, que e a de STATUS BOX e tem cor propria por status. Em
//    263 linhas o L e roxo enquanto a linha nao tem preenchimento nenhum — ler o L
//    classificaria essas 263 linhas AREP como Reunion. A leitura passou pra coluna H
//    (Fornecedor), que e coluna de dados.
//
// O roxo do Reunion neste arquivo e o tema 7 = accent4 = #8064A2 (conferido em
// xl/theme/theme1.xml). Aceitamos tambem o mesmo tom escrito como ARGB direto, caso a
// planilha passe a gravar a cor sem usar o tema.
const TEMA_REUNION = 7;
const ARGB_REUNION = '8064A2';
const COLUNA_DA_COR = 'H'; // coluna de dados — NUNCA a L (cor de status)

function corDePreenchimento(cell) {
  const fill = cell && cell.fill;
  if (!fill || fill.type !== 'pattern' || fill.pattern !== 'solid') return null;
  const fg = fill.fgColor || {};
  if (fg.argb) return { tipo: 'argb', valor: String(fg.argb).toUpperCase() };
  if (fg.theme !== undefined) return { tipo: 'theme', valor: fg.theme };
  return { tipo: 'desconhecido', valor: null };
}

function projetoPelaCorDaLinha(row) {
  const cor = corDePreenchimento(row.getCell(COLUNA_DA_COR));
  if (!cor) return 'AREP'; // sem preenchimento = AREP (spec secao 5)
  if (cor.tipo === 'theme') return cor.valor === TEMA_REUNION ? 'REUNION' : 'AREP';
  if (cor.tipo === 'argb') return cor.valor.slice(-6) === ARGB_REUNION ? 'REUNION' : 'AREP';
  return 'AREP';
}

async function lerAbaNotas(posicao, projetoFixo) {
  const buffer = await bufferNaPosicao(posicao);
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const ws = abaChamada(wb, 'NOTAS');
  if (!ws) {
    throw new Error('aba "NOTAS" nao encontrada no Cost Report. Abas do arquivo: ' + wb.worksheets.map((w) => w.name).join(', '));
  }
  const linhas = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return; // cabeçalho
    const projetoId = projetoFixo || projetoPelaCorDaLinha(row);
    linhas.push({
      linha: rowNumber,
      projetoId,
      colunaB: textoDaCelula(row, 'B'),
      colunaC: textoDaCelula(row, 'C'),
      colunaG: textoDaCelula(row, 'G'),
      colunaH: textoDaCelula(row, 'H'),
      colunaJ: textoDaCelula(row, 'J'),
      colunaK: numeroDaCelula(row, 'K'),
      colunaL: textoDaCelula(row, 'L'),
      colunaN: textoDaCelula(row, 'N'),
      colunaR: textoDaCelula(row, 'R'),
    });
  });
  return linhas;
}

// Colunas localizadas pelo NOME do cabeçalho, não por letra fixa: as abas têm layouts
// diferentes (na de equipe a empresa fica em J; na de prestação de serviço, em F) e o
// cabeçalho está na linha 3, não na 1. Mapeamento por letra fixa lia as colunas erradas.
async function lerPlanilhaContratos(posicao) {
  const buffer = await bufferNaPosicao(posicao);
  const wb = XLSX.read(buffer, { type: 'buffer' });
  const linhas = [];

  // Só a aba "EQUIPE E E FORNECEDORES" (spec 3.1). O arquivo é da diretoria de Contratos e
  // a automação só lê — não cabe a ela decidir excluir aba. Restringindo à aba certa, as
  // demais (inclusive CANCELADOS_DISTRATOS) simplesmente nunca entram na leitura.
  const ABA_CONTRATOS = 'equipe e e fornecedores';
  const abasAlvo = wb.SheetNames.filter((s) => normalizar(s) === ABA_CONTRATOS);
  if (abasAlvo.length === 0) {
    throw new Error('aba "EQUIPE E E FORNECEDORES" nao encontrada na planilha de contratos. Abas: ' + wb.SheetNames.join(', '));
  }

  for (const nomeAba of abasAlvo) {
    const grade = XLSX.utils.sheet_to_json(wb.Sheets[nomeAba], { header: 'A', raw: false, defval: '' });

    let iCab = -1;
    for (let i = 0; i < Math.min(grade.length, 10); i++) {
      if (Object.values(grade[i]).some((v) => normalizar(v) === 'status')) { iCab = i; break; }
    }
    if (iCab < 0) continue;

    const col = {};
    for (const [letra, valor] of Object.entries(grade[iCab])) {
      const h = normalizar(valor);
      if (h === 'status') col.status = letra;
      else if (h === 'nome') col.nome = letra;
      else if (h.includes('informacoes da empresa')) col.empresa = letra;
    }
    if (!col.status) continue;

    for (const linha of grade.slice(iCab + 1)) {
      const razaoSocial = col.empresa ? String(linha[col.empresa] || '').trim() : '';
      const nomeColaborador = col.nome ? String(linha[col.nome] || '').trim() : '';
      if (!razaoSocial && !nomeColaborador) continue; // linha vazia ou separador
      linhas.push({ razaoSocial, nomeColaborador, status: String(linha[col.status] || '').trim() });
    }
  }

  if (linhas.length === 0) {
    throw new Error('planilha de contratos veio sem nenhuma linha legivel — confira o formato do arquivo');
  }
  return linhas;
}

// Só o Cost da fonte desta passada (C.6). S01: a cor decide AREP/REUNION; S02: tudo SOFT_PRE.
// Sem fallback: projetos da config fora disso PARAM.
const cfg = $('Carregar config + perfis').first().json;
const fonteId = $('Trigger — fonte a processar').first().json.fonteId;
const projetosDaFonte = ((cfg.costs || {})[fonteId] || {}).projetos || [];
let projetoFixo;
if (projetosDaFonte.length === 1) projetoFixo = projetosDaFonte[0];
else if (projetosDaFonte.length === 2 && projetosDaFonte.includes('AREP') && projetosDaFonte.includes('REUNION')) projetoFixo = null;
else throw new Error('fonte "' + fonteId + '": projetos da config inesperados (' + JSON.stringify(projetosDaFonte) + ')');
const linhasDaFonte = await lerAbaNotas(0, projetoFixo);

const contratos = {
  AREP: await lerPlanilhaContratos(1),
  REUNION: await lerPlanilhaContratos(2),
  SOFT_PRE: await lerPlanilhaContratos(3),
};

const todasAsLinhas = linhasDaFonte;

// Os contratos NÃO vão em cada item, de propósito. O array do AREP tem ~60 KB; copiado
// nas ~3,9 mil linhas dá ~217 MB, que o n8n serializa a CADA salto de node — foi o que
// travou a VM (e2-small, 2 GB) na primeira execução em que o parse funcionou de verdade.
// Vai só no primeiro item, no campo contratosPorProjeto; a checagem de contrato lê de lá.
return todasAsLinhas.map((nota, indice) => ({
  json: {
    nota,
    ...(indice === 0 ? { contratosPorProjeto: contratos } : {}),
    config: cfg.config,
    cobrancas: cfg.cobrancas,
    apelidos: cfg.apelidos,
    perfil: cfg.perfis[nota.projetoId],
    dominioEmpresa: cfg.dominioEmpresa,
  },
}));

// Filtra só as linhas relevantes pra esta execução: candidatas a NOVO PEDIDO
// (Status Box = 'PROGRAMAR ATÉ [data]' ou variante de 'SOLICITAR') ou
// candidatas a MONITORAMENTO/COBRANÇA (Status Box = 'SOLICITADA MI').
// Linhas em qualquer outro estado (RECEBIDA MI, ENTREGUE, etc.) são ignoradas
// nesta fase — seção 3.1/3.1.1 do spec.md.

function ehVarianteSolicitar(statusBox) {
  return /^SOLICITAR/i.test((statusBox || '').trim());
}

// Escala de urgencia dentro de SOLICITAR (secao 3.1.4): 0 = mais urgente, 5 = menos.
// Literal ao spec: SO o sufixo "URG" e escala 0; qualquer outro sufixo cai na escala 1.
// Variantes reais hoje na planilha: "SOLICITAR" (32x) e "SOLICITAR / AGUARDAR DOCS" (1x).
// Nota: "SOLICITADA INFRA/BASE/MI" nao entram aqui — comecam com SOLICITADA, nao
// SOLICITAR, e nao casam com este filtro (so "SOLICITADA MI" tem tratamento proprio, no
// ramo de monitoramento).
const ESCALA_URGENTE = 0;
const ESCALA_PADRAO = 1;
const ESCALA_AGUARDAR_DOCS = 5;

function escalaDeUrgencia(statusBox) {
  const s = String(statusBox || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
  if (/AGUARDAR DOCS/.test(s)) return ESCALA_AGUARDAR_DOCS;
  // Variacoes de digitacao do mesmo token de urgencia contam todas como escala 0:
  // URG, URGENTE, URGENCIA (e URGÊNCIA — o acento ja caiu na normalizacao acima).
  // Continua sendo casamento de TOKEN dentro do texto, nao uma regra de escala nova.
  if (/\bURG(?:ENTE|ENCIA)?\b/.test(s)) return ESCALA_URGENTE;
  return ESCALA_PADRAO;
}

function extrairDataProgramarAte(statusBox, anoReferencia) {
  const m = /PROGRAMAR AT[ÉE]\s+(\d{1,2})[\/.](\d{1,2})(?:[\/.](\d{2,4}))?/i.exec(statusBox || '');
  if (!m) return null;
  const dia = parseInt(m[1], 10);
  const mes = parseInt(m[2], 10) - 1;
  const ano = m[3] ? (m[3].length === 2 ? 2000 + parseInt(m[3], 10) : parseInt(m[3], 10)) : anoReferencia;
  return new Date(ano, mes, dia);
}

const hoje = new Date();
const saida = [];

for (const item of $input.all()) {
  const { nota } = item.json;
  const dataProgramarAte = extrairDataProgramarAte(nota.colunaL, hoje.getFullYear());

  if (dataProgramarAte) {
    saida.push({ json: { ...item.json, fluxo: 'novo_pedido', gatilho: 'PROGRAMAR_ATE', dataProgramarAte: dataProgramarAte.toISOString() } });
  } else if (ehVarianteSolicitar(nota.colunaL)) {
    const escala = escalaDeUrgencia(nota.colunaL);
    saida.push({ json: {
      ...item.json,
      fluxo: 'novo_pedido',
      gatilho: 'SOLICITAR',
      escalaUrgencia: escala,
      // escala 5 = "SOLICITAR / AGUARDAR DOCS": e-mail SEMPRE rascunho, mesmo em
      // automatico + producao (unica excecao do sistema — secao 3.1.4). O flag viaja com
      // o item pra que a decisao de envio nao precise reinterpretar o texto do Status Box,
      // e a excecao nao possa vazar pra outra variante por engano.
      forcarRascunho: escala === ESCALA_AGUARDAR_DOCS,
    } });
  } else if (normalizarSimples(nota.colunaL) === 'solicitada mi') {
    saida.push({ json: { ...item.json, fluxo: 'monitoramento' } });
  }
  // demais status: ignorados nesta fase.
}

function normalizarSimples(t) { return (t || '').toLowerCase().trim(); }

return saida;

// 'Modo assistido' (secao 7.4): limite_linhas_execucao corta o numero de linhas
// processadas nesta execucao. null/0 = sem limite.
//
// ORDEM DE PRIORIDADE dentro do limite (confirmada por Claudio):
//   1o  SOLICITAR (e variantes) — pedido imediato, e o que a Michelle esta esperando sair
//   2o  PROGRAMAR ATE          — tem data marcada, aguenta a proxima execucao
//   3o  Monitoramento          — so se sobrar vaga; cobranca pode esperar
// Vale igual em homolog e producao.
//
// O corte era pela ordem da planilha: com limite baixo, uma leva de linhas de
// monitoramento no topo consumia as vagas e nenhum pedido saia.
//
// A ordenacao roda mesmo SEM limite. Nao muda o que e processado, so a ordem — e
// mantem o comportamento previsivel entre uma execucao limitada e uma sem limite.
//
// MUDANCA (09/09, spec.md secao 7.4) — O LIMITE E UM TETO POR PROJETO.
// Nao e cota fixa: se o projeto tiver menos linhas elegiveis que o teto, processa todas,
// sem forcar chegar no numero. E o teto e POR PROJETO (AREP, Reunion, Soft Pre cada um com
// o seu), nao por arquivo — importante porque AREP e Reunion dividem o MESMO arquivo fisico
// (Cost Report S01, diferenciados por cor de linha, secao 6). Um teto por arquivo faria os
// dois disputarem a mesma cota; por projeto, cada um e avaliado separadamente.
// Ex.: com limite=20, AREP com 2 linhas e Reunion com 15 rodam por inteiro (2 e 15).

function projetoDe(d) {
  return (d && d.nota && d.nota.projetoId) || 'DESCONHECIDO';
}

function prioridade(d) {
  if (d.fluxo === 'novo_pedido' && d.gatilho === 'SOLICITAR') return 0;
  if (d.fluxo === 'novo_pedido' && d.gatilho === 'PROGRAMAR_ATE') return 1;
  if (d.fluxo === 'monitoramento') return 2;
  return 3; // nao previsto: fica por ultimo em vez de furar a fila
}

// Desempate DENTRO da categoria SOLICITAR: escala 0 -> 1 -> 5 (secao 3.1.4). Nas outras
// categorias nao existe escala, entao todas empatam em 0 e a ordem da planilha decide.
function subPrioridade(d) {
  if (d.fluxo === 'novo_pedido' && d.gatilho === 'SOLICITAR') {
    return typeof d.escalaUrgencia === 'number' ? d.escalaUrgencia : 1;
  }
  return 0;
}

// sort do JS e estavel: dentro da mesma prioridade, a ordem da planilha e preservada
function ordenar(itens) {
  return itens.slice().sort((a, b) =>
    (prioridade(a.json) - prioridade(b.json)) || (subPrioridade(a.json) - subPrioridade(b.json)));
}

const config = $('Carregar config + perfis').first().json.config;
const limite = config && config.limite_linhas_execucao;

const todos = ordenar($input.all());
if (!limite || limite <= 0) return todos;

// aplica o teto DENTRO de cada projeto, preservando a ordem de prioridade
const contagem = {};
const escolhidos = [];
for (const item of todos) {
  const p = projetoDe(item.json);
  contagem[p] = (contagem[p] || 0) + 1;
  if (contagem[p] <= limite) escolhidos.push(item);
}
return escolhidos;

// Checagem de contrato — passo 1 (spec 3.1): a coluna N do Cost Report.
// Aqui o critério é "CONTÉM assinado" (o spec dá "OK - Assinado" como exemplo válido) —
// diferente do critério da planilha de Contratos, que é o literal exato. São regras
// distintas de propósito; não dá pra unificar as duas.
//
// Se a coluna N já resolve, nem planilha nem Gmail precisam ser consultados. Se não
// resolve, as DUAS checagens rodam em paralelo (spec 3.1), sem prioridade entre si.
// Itens de fluxo='monitoramento' não passam por checagem de contrato nenhuma.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

return $input.all().map((item) => {
  const { nota, fluxo } = item.json;
  const chaveLinha = nota ? (nota.projetoId + '|' + nota.linha) : null;

  if (fluxo !== 'novo_pedido') {
    return { json: { ...item.json, chaveLinha, contratoResolvido: true } };
  }

  const liberado = normalizar(nota.colunaN).includes('assinado');
  return { json: {
    ...item.json,
    chaveLinha,
    liberado,
    motivoLiberacao: liberado ? 'coluna_n' : undefined,
    // coluna N já está preenchida: não há o que reescrever nela
    contratoResolvido: liberado,
  } };
});

// ETAPA 2 do spec 3.1 (simplificada em 11/09) — e a UNICA que confirma "OK - ASSINADO".
//
// A ficha cadastral real e SEMPRE .xlsx (confirmado por Claudio; exemplo real
// "BR_SMTC_S01_FICHA CADASTRAL....xlsx"). Os PDFs anexados sao documentos de APOIO da empresa
// (NIRE, CNPJ, contrato de locacao) — provam que a empresa existe, nao que a ficha e daquela
// pessoa. Por isso so o .xlsx e lido aqui, com exceljs (ja disponivel na VM: sem IA, sem PDF).
//
// Se nenhum candidato tiver .xlsx, a linha fica PENDENTE — mesmo que a Etapa 1 tenha achado
// algo "quase certo". Nunca liberar so pela Etapa 1: foi exatamente isso que produziu o falso
// positivo do caso "Vanessa Paes".
//
// A correspondencia e a MESMA da checagem de Contratos: documento primeiro (identifica de
// forma unica), nome com tolerancia de 1º/ultimo token depois.

const ExcelJS = require('exceljs');

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function digitosDeDocumento(texto) {
  const m = String(texto || '').match(/\d[\d.\-/]{7,}/);
  if (!m) return null;
  const d = m[0].replace(/\D/g, '');
  return d.length >= 8 ? d : null;
}

function documentosBatem(a, b) {
  if (!a || !b) return false;
  if (a === b) return true;
  const curto = a.length <= b.length ? a : b;
  const longo = a.length <= b.length ? b : a;
  return curto.length >= 8 && longo.indexOf(curto) === 0;
}

function distanciaAte1(a, b) {
  if (a === b) return true;
  const dif = Math.abs(a.length - b.length);
  if (dif > 1) return false;
  const curta = a.length <= b.length ? a : b;
  const longa = a.length <= b.length ? b : a;
  let i = 0;
  while (i < curta.length && curta[i] === longa[i]) i++;
  let j = 0;
  while (j < curta.length - i && curta[curta.length - 1 - j] === longa[longa.length - 1 - j]) j++;
  return i + j >= curta.length - (dif === 0 ? 1 : 0);
}

function tokensDoNome(nome) {
  return normalizar(String(nome || '').replace(/^[\d.\-/\s]+/, '')).split(' ').filter(Boolean);
}

function nomesBatem(a, b) {
  const ta = tokensDoNome(a);
  const tb = tokensDoNome(b);
  if (!ta.length || !tb.length) return false;
  return distanciaAte1(ta[0], tb[0]) && distanciaAte1(ta[ta.length - 1], tb[tb.length - 1]);
}

// "FICHA" no nome do arquivo e sinal de que e a ficha certa, e nao outra planilha qualquer
// que veio junto — por isso essas vem primeiro na ordem de tentativa (spec 3.1).
function planilhasDoItem(item) {
  const props = Object.keys((item && item.binary) || {});
  const xlsx = props.filter((pr) => /\.xlsx$/i.test(String(item.binary[pr].fileName || '')));
  const comFicha = xlsx.filter((pr) => /ficha/i.test(String(item.binary[pr].fileName || '')));
  const resto = xlsx.filter((pr) => !comFicha.includes(pr));
  return comFicha.concat(resto);
}

async function textosDaPlanilha(indice, prop) {
  const buffer = await this.helpers.getBinaryDataBuffer(indice, prop);
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const valores = [];
  for (const ws of wb.worksheets) {
    ws.eachRow({ includeEmpty: false }, (row) => {
      row.eachCell({ includeEmpty: false }, (cell) => {
        const v = cell.value;
        if (v === null || v === undefined) return;
        const texto = typeof v === 'object' ? (v.text || v.result || v.richText && v.richText.map((r) => r.text).join('') || '') : v;
        const s = String(texto).trim();
        if (s) valores.push(s);
      });
    });
  }
  return valores;
}

function fichaConfere(valores, alvos) {
  for (const alvo of alvos) {
    const docAlvo = digitosDeDocumento(alvo);
    for (const v of valores) {
      if (docAlvo && documentosBatem(digitosDeDocumento(v), docAlvo)) return { ok: true, por: 'documento', valor: v.slice(0, 60) };
      if (nomesBatem(v, alvo)) return { ok: true, por: 'nome', valor: v.slice(0, 60) };
    }
  }
  return { ok: false };
}

const origem = $('Preparar checagem paralela de contrato').all().map((i) => i.json);
const candidatos = $('Etapa 1 — candidatos plausíveis').all().map((i) => i.json);
const entradas = $input.all();

// O node de Gmail devolve UM item por item de entrada, na mesma ordem — por isso o pareamento
// aqui e por INDICE contra a saida da Etapa 1, e nao por pairedItem: o node de Gmail substitui
// o json do item pela mensagem, e o chaveLinha que a Etapa 1 colocou se perderia no caminho.
const porLinha = new Map();

for (let k = 0; k < entradas.length; k++) {
  const cand = candidatos[k];
  if (!cand || cand.semCandidatos) continue; // sentinela da Etapa 1: nenhum candidato plausivel
  const linha = origem[cand.indiceOrigem];
  if (!linha) continue;

  const alvos = [linha.nomeColaborador, linha.nota && linha.nota.colunaH].filter(
    (v) => v && !/FALTA INFORMA/i.test(String(v)),
  );
  if (!alvos.length) continue;

  const item = entradas[k];
  if (item.json && item.json.error) continue;

  for (const prop of planilhasDoItem(item)) {
    let resultado;
    try {
      const valores = await textosDaPlanilha.call(this, k, prop);
      resultado = fichaConfere(valores, alvos);
    } catch (e) {
      // planilha corrompida ou protegida: nao confirma, e tambem nao derruba a execucao
      resultado = { ok: false, erro: String(e.message).slice(0, 120) };
    }
    if (resultado.ok) {
      porLinha.set(cand.chaveLinha, {
        arquivo: String(item.binary[prop].fileName || '').slice(0, 80),
        por: resultado.por,
        valorNaFicha: resultado.valor,
      });
      break;
    }
  }
}

// Uma saida por LINHA DE ORIGEM, sempre — o consolidador precisa do par completo das duas
// checagens, inclusive quando nao houve candidato nenhum.
return origem.map((linha) => {
  const prova = porLinha.get(linha.chaveLinha);
  return { json: {
    ...linha,
    fonteChecagem: 'ficha_cadastral',
    confirmado: !!prova,
    provaFicha: prova || null,
    atualizarColunaNPara: prova ? 'OK - ASSINADO' : undefined,
  } };
});

// Interpreta a resposta da IA — nunca lanca excecao, falha vira situacaoNaoMapeada
// (regra geral de seguranca, secao 3.2 item 6: nunca adivinhar, sempre alertar).
//
// DOIS consertos, ambos vistos na execucao 75:
//
// 1. A IA devolve o JSON dentro de um bloco cercado (```json ... ```), que e comportamento
//    normal do modelo. JSON.parse direto no texto falhava e a linha virava "situacao nao
//    mapeada" mesmo com a resposta PERFEITA.
// 2. O node HTTP SUBSTITUI o json do item pela resposta da API: nota, perfil, config,
//    apelidos, liberado, gatilho — tudo se perdia aqui. O alerta no Telegram saiu
//    literalmente como "undefined", e a montagem do e-mail tambem ficaria sem os dados da
//    linha. O contexto e reanexado casando pelo pairedItem.

function indiceDeOrigem(item) {
  const p = item.pairedItem;
  if (p === undefined || p === null) return null;
  if (typeof p === 'number') return p;
  if (Array.isArray(p)) return p.length && p[0] ? p[0].item : null;
  return p.item === undefined ? null : p.item;
}

function extrairJson(texto) {
  const t = String(texto || '').trim();
  const cercado = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const bruto = cercado ? cercado[1] : t;
  const inicio = bruto.indexOf('{');
  const fim = bruto.lastIndexOf('}');
  return inicio >= 0 && fim > inicio ? bruto.slice(inicio, fim + 1) : bruto;
}

function parseRespostaIA(textoResposta) {
  try {
    const obj = JSON.parse(extrairJson(textoResposta));
    if (!obj || !obj.tipoLinha) return { situacaoNaoMapeada: 'Resposta da IA sem tipoLinha: ' + String(textoResposta).slice(0, 300) };
    return obj;
  } catch (e) {
    return { situacaoNaoMapeada: 'Resposta da IA nao e JSON valido: ' + String(textoResposta).slice(0, 300) };
  }
}

// Cargo sem numeracao (spec 3.1, item 6). A regra tambem foi pro prompt, mas nao dependemos
// do modelo obedecer: aqui e deterministico. Tira numeracao no FIM do cargo, com ou sem
// separador ("ASS. DE CONTROLLER 1", "CONTRARREGRA - 2", "CAMERA nº 3" -> sem o numero).
// Numero no meio do texto e preservado, que nao e numeracao de posto.
function cargoSemNumeracao(cargo) {
  if (!cargo || cargo === 'FALTA INFORMACAO' || cargo === 'FALTA INFORMAÇÃO') return cargo;
  // O separador e OBRIGATORIO ([\s\-–—]+): sem isso, "MOTORISTA 4X4" perdia o 4 final.
  // So conta como numeracao o numero destacado do resto do texto.
  const limpo = String(cargo).replace(/[\s\-–—]+(?:n[º°o]?\.?\s*)?\d+\s*$/i, '').trim();
  return limpo || cargo; // se sobrar vazio, mantem o original em vez de apagar o campo
}

const origem = $('Preparar chamada da IA (coluna J)').all().map((i) => i.json);

return $input.all().map((item, i) => {
  const idx = indiceDeOrigem(item);
  const contexto = (idx !== null && origem[idx]) ? origem[idx] : (origem[i] || {});
  const textoResposta = item.json.content && item.json.content[0] ? item.json.content[0].text : '';
  const resultado = parseRespostaIA(textoResposta);
  if (resultado.cargo) resultado.cargo = cargoSemNumeracao(resultado.cargo);
  return { json: { ...contexto, ...resultado } };
});

// Monta o texto do alerta AQUI, e nao na expressao do node do Telegram.
// Na execucao 75 a expressao era '... ' + $json.nota.projetoId + ' ...' e, com nota
// ausente, o n8n resolveu a expressao inteira como "undefined" — a mensagem chegou, mas
// sem nenhuma informacao. Montando no Code, um campo faltando vira "?" e o resto do alerta
// continua legivel.
return $input.all().map((item) => {
  const d = item.json;
  const nota = d.nota || {};
  const texto = [
    '⚠️ Situação não mapeada (Fase 1)',
    '',
    'Projeto: ' + (nota.projetoId || '?'),
    'Linha: ' + (nota.linha || '?'),
    'Fornecedor/Descrição: ' + (nota.colunaH || nota.colunaJ || '?'),
    '',
    String(d.situacaoNaoMapeada || 'sem detalhe'),
  ].join('\n');
  return { json: { ...d, acao: 'alerta_situacao_nao_mapeada', textoAlerta: texto } };
});

// Monta o e-mail de pedido pra caso COLABORADOR (secoes 3.2, 3.3, 3.4).
// Gateia 'liberado' aqui (nao mais antes da IA) e resolve destinatario/assunto por ambiente (secao 7.4).

const MESES_ABREV_PT = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const MARCADOR_PROJETO = { REUNION: 'REUNION - PEDIDO DE NOTAS', SOFT_PRE: 'SOFT PRE - PEDIDO NOTAS', AREP: 'AREP - PEDIDO DE NOTAS' };
const TOMADOR_HTML = '<p><b>Tomador</b><br>\n' +
  'BOXFISH PRODUTORA DE PROGRAMAS TELEVISIVOS, INTERNET E FILMES PUBLICITÁRIOS LTDA.<br>\n' +
  'Endereço: Rua Butantã, 194, sala 24, Pinheiros.<br>\n' +
  'CEP 05.424-000 - São Paulo, SP<br>\n' +
  'CNPJ: 14.788.649/0001-23<br>\n' +
  'IM: 4.436.095-9<br>\n' +
  'IE: ISENTA</p>';
const AVISO_HTML = '<p><i>"Os dados bancários considerados para pagamento são os que estão cadastrados.<br>\n' +
  'O cadastro é feito baseado nas informações cedidas pelo contratado através do preenchimento de ficha cadastral da Box.<br>\n' +
  'Qualquer alteração bancária ou mudança na forma de pagamento deve ser notificada por e-mail pelo contratado e se faz necessário atualização da ficha cadastral e envio prévio ao responsável financeiro do projeto."</i></p>' +
  '\n<p>Muito obrigada!<br>\nBjs 🌷</p>';
const IMPORTANTE_HTML = '<p><b><span style="color:#FF0000;">Importante: Peço a gentileza de enviar a sua nota nestes e-mails:</span></b><br>\n' +
  'financeiro@novorealitybox.com<br>\nfinanceiro1@novorealitybox.com</p>';
const EMAIL_TESTE_HOMOLOG = 'grandesnegocioseoportunidades+colaborador@gmail.com';
// Cópia (CC) por ambiente — seção 3.1.7. Em homolog vai pro endereço de teste da
// Danielle; em produção, pro e-mail real da controller. O destinatário principal
// segue a mesma lógica: fixo de teste em homolog, coluna R em produção.
const EMAIL_COPIA_HOMOLOG = 'grandesnegocioseoportunidades+danielle@gmail.com';
const EMAIL_COPIA_PRODUCAO = 'financeiro@novorealitybox.com'; // seção 7.4 — endereço de teste do Claudio (Danielle homolog)

// ─── Formatação do e-mail — valores EXATOS da seção 3.5 do spec, extraídos de um e-mail
// real de produção. Vale igual em homolog: o e-mail de teste tem que ser visualmente
// idêntico ao de produção, mudando só destinatário e credencial (seções 7.4 e 3.5).
const FONTE_EMAIL = 'Verdana, Geneva, sans-serif';
const COR_DATA_ENVIO = '#cc0000';      // só a data do "enviada até o dia" — em negrito (3.5)
const FUNDO_VENCIMENTO = '#CFE2F3';    // só os números da data de vencimento
const FUNDO_BLOCO_EMITIR = '#FFE599';  // bloco "N- Emitir ... no valor de R$ X"
const COR_IMPORTANTE = '#FF0000';      // "Importante: Peço a gentileza..."

function envolverCorpo(partes) {
  return '<div style="font-family:' + FONTE_EMAIL + ';">\n' + partes.filter(Boolean).join('\n') + '\n</div>';
}

// "...enviada até o dia DD/MM" -> cor só na data. "vencimento em DD/MM/AAAA." -> negrito no
// trecho inteiro, com highlight só nos números da data.
// Abertura por tipo de documento do e-mail:
//   'recibo_e_nf' -> fornecedor REC+NF (dois documentos, seção 3.2.1)
//   'fatura'      -> fornecedor só RECIBO. NUNCA "nota fiscal" aqui: locação se cobra por
//                    recibo/fatura, e trocar a palavra é erro fiscal (seção 3.2).
//   'varias_nf'   -> colaborador com mais de um bloco -> plural (seção 3.2.1)
//   'uma_nf'      -> colaborador com um bloco só
function paragrafoAbertura(dataEnvio, dataVencimento, tipoAbertura) {
  const VERBOS = {
    recibo_e_nf: 'Seguem as instruções para a emissão do RECIBO e da NOTA FISCAL que deverão ser enviadas ',
    fatura: 'Seguem as instruções para a emissão da sua FATURA que deverá ser enviada ',
    varias_nf: 'Seguem as instruções para a emissão das suas notas fiscais que deverão ser enviadas ',
    uma_nf: 'Seguem as instruções para a emissão da sua nota fiscal que deverá ser enviada ',
  };
  const verbo = VERBOS[tipoAbertura] || VERBOS.uma_nf;
  // "até o dia DD/MM" INTEIRO em vermelho; só os números da data em negrito (3.5).
  const ateODia = '<span style="color:' + COR_DATA_ENVIO + ';"><b>até o dia ' + formatarDataDiaMes(dataEnvio) + '</b></span>';
  // "vencimento em DD/MM/AAAA." INTEIRO com o highlight; o ponto final fica DENTRO do
  // highlight e FORA do negrito (3.5).
  const vencimento = '<span style="background-color:' + FUNDO_VENCIMENTO + ';">' +
    '<b>vencimento em ' + formatarDataBR(dataVencimento) + '</b>.</span>';
  return '<p>' + verbo + ateODia + ' com ' + vencimento + '</p>';
}

function blocoEmitir(numero, textoDocumento, valor) {
  const valorFmt = valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return '<p><span style="background-color:' + FUNDO_BLOCO_EMITIR + ';">' + numero +
    '- Emitir ' + textoDocumento + ' no valor de <b>R$ ' + valorFmt + '</b> com os dados abaixo no corpo da nota:</span></p>';
}

function blocoDadosBancarios() {
  // Sem <p> vazio entre "Período de" e "Dados bancários": a 3.5 (referência Paulo Bento)
  // pede parágrafos sequenciais, com o espaçamento vindo só da margem padrão do <p>.
  return '<p><b>Dados bancários:</b></p>\n<p><b>Chave pix:</b></p>\n' +
    '<p>---------------------------------------------------------------------</p>';
}

function formatarDataBR(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear(); }
// Data do "ate o dia" no CORPO: DD/MM, sem ano — formato diferente do vencimento
// (DD/MM/AAAA), de proposito (3.5, confirmado com e-mail padrao de producao).
// Nao confundir com formatarDataCurta, que e DD.MM com PONTO e vale pro ASSUNTO.
function formatarDataDiaMes(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0'); }
function formatarDataCurta(d) { return String(d.getDate()).padStart(2,'0') + '.' + String(d.getMonth()+1).padStart(2,'0'); }
function montarPeriodoTexto(periodo, tipoEmissao) {
  if (!periodo) return '';
  const PALAVRA_CHAVE = { JOB: 'JOB', DIARIA: 'DIÁRIA', PACOTE: 'PACOTE' };
  const palavra = PALAVRA_CHAVE[tipoEmissao];
  return palavra ? (periodo + ' (' + palavra + ')') : periodo;
}
function montarRefAssuntoColaborador(tipoEmissao, dataEnvio, parcela, mesesRef) {
  if (tipoEmissao === 'JOB') return parcela ? ('REF. JOB (' + parcela + ')') : 'REF. JOB';
  if (tipoEmissao === 'DIARIA') return 'REF. DIÁRIA';
  if (tipoEmissao === 'PACOTE') return 'REF. PACOTE';
  // Mais de um bloco com meses de referencia diferentes -> cita TODOS (spec 3.2,
  // "COLABORADOR, 2 PERIODOS, MESMO VENCIMENTO"): "REF. JUL E AGO".
  if (mesesRef && mesesRef.length > 1) return 'REF. ' + mesesRef.join(' E ');
  // Caso de bloco unico: mes do ENVIO, nao do vencimento (evidencia: exemplo Media Arts,
  // secao 3.2.1). Comportamento ja validado — nao muda.
  return 'REF. ' + MESES_ABREV_PT[dataEnvio.getMonth()];
}

function montarCorpoEmailColaborador(p) {
  // Um bloco numerado POR LINHA da planilha (spec 3.2/3.2.1): cada linha e um documento
  // distinto, com seu proprio periodo e valor. Com uma linha so, sai identico ao formato
  // anterior — o "1-" ja era o numero usado.
  const blocos = p.blocos.map((b, i) => [
    blocoEmitir(i + 1, 'nota fiscal', b.valor),
    '<p>Ref. "' + p.textoRef + '"</p>',
    '<p><b>Serviço Prestado como</b> ' + b.cargo + '</p>',
    '<p><b>Colaborador:</b> ' + p.nomeColaborador + '</p>',
    b.periodoTexto ? ('<p><b>Período de</b> ' + b.periodoTexto + '</p>') : '',
    blocoDadosBancarios(),
  ].filter(Boolean).join('\n'));

  return envolverCorpo([
    '<p>Olá ' + p.primeiroNome + '! Tudo bem? 😊</p>',
    paragrafoAbertura(p.dataEnvio, p.dataVencimento, p.blocos.length > 1 ? 'varias_nf' : 'uma_nf'),
    TOMADOR_HTML,
    blocos.join('\n'),
    IMPORTANTE_HTML,
    AVISO_HTML,
  ]);
}

function normalizarNome(t) {
  return t ? String(t).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim().replace(/\s+/g, ' ') : '';
}

// ─── Período em ordem cronológica ASCENDENTE (spec 3.2.1) ───
// A planilha às vezes traz as datas invertidas por erro de digitação ("05/08 A 26/07") e o
// e-mail não pode reproduzir isso.
//
// Sem ano na origem, "26/12 A 05/01" é virada de ano legítima, não inversão. Das duas
// leituras possíveis escolhemos a de PERÍODO MAIS CURTO — período de trabalho tem dias ou
// semanas: 26/12→05/01 dá 10 dias e vence 05/01→26/12, que daria 355; e o par de fato
// invertido "05/08 A 26/07" é corrigido pelo mesmo critério, sem regra especial.
function diasEntre(diaA, mesA, diaB, mesB) {
  const ini = Date.UTC(2001, mesA - 1, diaA);
  let fim = Date.UTC(2001, mesB - 1, diaB);
  if (fim < ini) fim = Date.UTC(2002, mesB - 1, diaB); // virou o ano
  return (fim - ini) / 86400000;
}

function normalizarPeriodo(periodo) {
  const txt = String(periodo || '');
  const datas = txt.match(/\d{1,2}\s*\/\s*\d{1,2}/g);
  if (!datas || datas.length < 2) return txt;
  const [a, b] = datas;
  const pa = a.split('/').map((x) => parseInt(x, 10));
  const pb = b.split('/').map((x) => parseInt(x, 10));
  const comoEscrito = diasEntre(pa[0], pa[1], pb[0], pb[1]);
  const invertido = diasEntre(pb[0], pb[1], pa[0], pa[1]);
  if (invertido >= comoEscrito) return txt;
  let n = 0;
  return txt.replace(/\d{1,2}\s*\/\s*\d{1,2}/g, () => (n++ === 0 ? b : a));
}

// Meses citados por um período. Um período que atravessa a virada do mês devolve OS DOIS
// (spec 3.2.1) — não escolhe um. Já vem em ordem cronológica, porque roda sobre o período
// normalizado.
function mesesDoPeriodo(periodo) {
  const datas = String(periodo || '').match(/\d{1,2}\s*\/\s*\d{1,2}/g) || [];
  const meses = [];
  for (const d of datas) {
    const mes = parseInt(d.split('/')[1], 10);
    if (mes >= 1 && mes <= 12) {
      const nome = MESES_ABREV_PT[mes - 1];
      if (meses.indexOf(nome) === -1) meses.push(nome);
    }
  }
  return meses;
}

// O apelido de projeto (apelidos.json) e so o identificador: "AREP", "SMTC - S01 | REUNION".
// Ja o prefixo_assunto_pedido do perfil vem com "| EMISSAO DE NF" embutido (spec secao 6).
// Como o assunto concatena a palavra do documento logo depois, usar o prefixo cru no
// fallback duplicava o trecho ("... | EMISSAO DE NF | EMISSAO DE NF | REF. ..."). Nao
// aparecia em execucao porque hoje o apelidos.json cobre os 3 projetos e o fallback nunca
// roda — mas passaria a aparecer se um projeto sumisse do arquivo.
function apelidoDoPerfil(perfil) {
  return String((perfil && perfil.prefixo_assunto_pedido) || '')
    .replace(/\s*\|\s*EMISS[ÃA]O DE .*$/i, '')
    .trim();
}
function ehModoAutomatico(config) { return config && config.modo === 'automatico'; }
// Status Box que ainda representam "antes do envio". Só esses podem virar "SOLICITADA MI"
// (spec 3.1.8): se a linha ja avancou (ENTREGUE MI, ENTREGUE MI R1...), a automacao nao pode
// regredir um estagio alcancado manualmente.
function statusBoxAindaAntesDoEnvio(statusBox) {
  const s = String(statusBox || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();
  return /^PROGRAMAR ATE/.test(s) || /^SOLICITAR/.test(s);
}

// Compara so a data do calendario, ignorando hora.
function chegouNaDataAlvo(dataAlvoISO, hoje) {
  if (!dataAlvoISO) return true;
  const alvoYMD = String(dataAlvoISO).slice(0, 10);
  const hojeYMD = new Date(hoje.getTime() - hoje.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  return hojeYMD >= alvoYMD;
}

function decidirAcaoEnvio(gatilho, modoAutomatico, forcarRascunho, contexto) {
  // "SOLICITAR / AGUARDAR DOCS" (escala 5) SEMPRE fica em rascunho, mesmo em
  // MODO_EXECUCAO=automatico e ambiente producao — unica excecao do sistema (secao 3.1.4).
  // O flag vem pronto do node de filtro: nao reinterpretamos o Status Box aqui, pra que a
  // excecao nao possa vazar pra outras variantes.
  if (forcarRascunho) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };

  // ── PROGRAMAR ATE (spec 3.1.8) ──────────────────────────────────────────────
  // A API do Gmail nao tem envio agendado — isso so existe na interface web. O contorno e
  // criar o rascunho desde ja e enviar numa execucao do dia do prazo.
  if (gatilho === 'PROGRAMAR_ATE') {
    const ctx = contexto || {};
    const rascunhoGuardado = ctx.estado && ctx.estado.draftId;

    // ainda nao existe rascunho -> cria agora. Coluna L NAO muda (item 2 da 3.1.8).
    if (!rascunhoGuardado) {
      return { acaoGmail: 'criar_rascunho', atualizarColunaL: false, programado: true };
    }
    // ja existe rascunho e a data nao chegou -> nao faz nada, nao duplica (item 3)
    if (!chegouNaDataAlvo(ctx.dataAlvo, ctx.hoje)) {
      return { acaoGmail: 'aguardando_data', atualizarColunaL: false };
    }
    // chegou a data, mas modo rascunho nunca envia sozinho (item 4)
    if (!modoAutomatico) {
      return { acaoGmail: 'aguardando_revisao_manual', atualizarColunaL: false };
    }
    // chegou a data em modo automatico -> o ramo de envio checa se o rascunho existe.
    // Coluna L fica false AQUI de proposito: quem decide grava-la e o ramo, depois de
    // confirmar o envio (spec 3.1.5).
    return { acaoGmail: 'enviar_programado', atualizarColunaL: false, draftIdProgramado: ctx.estado.draftId };
  }

  if (!modoAutomatico) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  return { acaoGmail: 'enviar_direto', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
}

const hoje = new Date();
const saida = [];
const grupos = new Map();

// 1a passada: o que nao gera e-mail sai por linha; o resto e agrupado.
// Agrupamento por projeto + colaborador + vencimento (spec 3.2, "COLABORADOR, 2 PERIODOS,
// MESMO VENCIMENTO"): duas linhas do mesmo colaborador vencendo no mesmo dia viram UM
// e-mail com dois blocos numerados, nao dois e-mails.
for (const item of $input.all()) {
  const d = item.json;

  if (!d.liberado) {
    saida.push({ json: { ...d, acao: 'pendente_contrato' } });
    continue;
  }

  // Deduplicação do pedido (3.1.6) — SÓ em produção. Se já existe entrada em
  // cobrancas.json para esta linha com threadId preenchido, o pedido já foi criado antes
  // e a linha só continua batendo no filtro porque o Status Box ainda não foi atualizado
  // à mão. Não gera e-mail novo; segue elegível pro monitoramento da 3.1.1.
  //
  // Em homolog não há trava, de propósito (3.1.6): o Claudio controla quais linhas
  // processar mudando o Status Box na planilha de teste.
  //
  // A chave é a MESMA que o fluxo grava em cobrancas.json (retranca + '_L' + linha) — usar
  // aqui uma chave diferente da que é gravada faria a checagem nunca casar.
  const chaveDedup = d.perfil.retranca + '_L' + d.nota.linha;
  const entradaAnterior = (d.cobrancas || {})[chaveDedup];
  if (d.config && d.config.ambiente === 'producao' && entradaAnterior && entradaAnterior.threadId) {
    saida.push({ json: { ...d, acao: 'pedido_ja_criado', chaveCobranca: chaveDedup, threadIdExistente: entradaAnterior.threadId } });
    continue;
  }

  const nomeItem = (d.nomeColaborador === 'FALTA INFORMAÇÃO' || d.nomeColaborador === 'FALTA INFORMACAO')
    ? 'FALTA INFORMAÇÃO'
    : (d.nomeColaborador || d.nota.colunaH);
  const chave = [d.nota.projetoId, normalizarNome(nomeItem), d.nota.colunaG].join('|');
  if (!grupos.has(chave)) grupos.set(chave, []);
  grupos.get(chave).push({ ...d, nomeItem });
}

// 2a passada: um e-mail por grupo.
for (const grupo of grupos.values()) {
  const d = grupo[0];

  const nomeColaborador = d.nomeItem;
  const primeiroNome = (nomeColaborador === 'FALTA INFORMAÇÃO' ? 'Colaborador' : nomeColaborador).split(' ')[0];

  const blocos = grupo.map((linha) => {
    const cargo = (linha.cargo === 'FALTA INFORMAÇÃO' || linha.cargo === 'FALTA INFORMACAO')
      ? 'FALTA INFORMAÇÃO'
      : (linha.cargo || linha.nota.colunaJ);
    const tipo = linha.tipoEmissao || 'NF_NORMAL';
    const periodo = normalizarPeriodo(linha.periodo);
    return {
      cargo,
      valor: linha.nota.colunaK,
      periodoTexto: montarPeriodoTexto(periodo, tipo),
      meses: mesesDoPeriodo(periodo),
    };
  });

  const temLacuna = nomeColaborador === 'FALTA INFORMAÇÃO' || blocos.some((b) => b.cargo === 'FALTA INFORMAÇÃO');

  const dataVencimento = new Date(d.nota.colunaG);
  const dataBase = d.gatilho === 'PROGRAMAR_ATE' ? new Date(d.dataProgramarAte) : hoje;
  const dataEnvio = d.gatilho === 'PROGRAMAR_ATE' ? (function(){ const dd = new Date(dataBase); dd.setDate(dd.getDate()+5); return dd; })() : dataBase;

  const tipoEmissao = d.tipoEmissao || 'NF_NORMAL';
  // Ordem de primeira aparicao (ordem da planilha), nao ordenada por numero do mes: um
  // periodo DEZ + JAN sairia invertido se ordenasse pelo indice.
  // Ordem: cronológica DENTRO de cada bloco (o normalizarPeriodo garante), e ordem de
  // aparição na planilha ENTRE blocos — ordenar por número do mês inverteria um par
  // DEZ + JAN (spec 3.2.1).
  const mesesRef = [];
  for (const b of blocos) for (const m of b.meses) if (mesesRef.indexOf(m) === -1) mesesRef.push(m);

  const refAssunto = montarRefAssuntoColaborador(tipoEmissao, dataEnvio, d.parcela, mesesRef);
  const apelidoAtual = (d.apelidos && d.apelidos[d.nota.projetoId] && d.apelidos[d.nota.projetoId].length) ? d.apelidos[d.nota.projetoId][d.apelidos[d.nota.projetoId].length - 1] : apelidoDoPerfil(d.perfil);

  const corpo = montarCorpoEmailColaborador({ primeiroNome, dataEnvio, dataVencimento, textoRef: d.perfil.texto_ref, nomeColaborador, blocos });
  let assunto = apelidoAtual + ' | EMISSÃO DE NF | ' + refAssunto + ' (ENVIAR ATÉ ' + formatarDataCurta(dataEnvio) + ') | ' + nomeColaborador;
  // Escala 0 ("SOLICITAR URG") leva "URG |" no inicio do assunto (secoes 3.1.4 e 3.5).
  if (grupo.some((l) => l.escalaUrgencia === 0)) assunto = 'URG | ' + assunto;

  // Ambiente troca APENAS o destinatario e a credencial (spec 7.4 e 3.5): o e-mail de
  // homologacao tem que ser identico em conteudo ao de producao.
  const ehHomolog = d.config && d.config.ambiente === 'homolog';
  const emailDestino = ehHomolog ? EMAIL_TESTE_HOMOLOG : d.nota.colunaR;
  const emailCopia = ehHomolog ? EMAIL_COPIA_HOMOLOG : EMAIL_COPIA_PRODUCAO;

  const decisao = decidirAcaoEnvio(d.gatilho, ehModoAutomatico(d.config), grupo.some((l) => l.forcarRascunho), {
    estado: (d.cobrancas || {})[d.perfil.retranca + '_L' + d.nota.linha],
    dataAlvo: d.dataProgramarAte,
    hoje,
  });

  saida.push({ json: {
    ...d,
    acao: decisao.acaoGmail,
    // PROGRAMAR ATE: viaja junto pro node que grava cobrancas.json (3.1.8)
    dataAlvoEnvio: decisao.programado ? d.dataProgramarAte : undefined,
    draftIdProgramado: decisao.draftIdProgramado,
    atualizarColunaL: decisao.atualizarColunaL,
    novoValorColunaL: decisao.novoValorColunaL,
    emailDestino,
    emailCopia,
    assunto,
    corpoHtml: corpo,
    marcadores: ['IA', MARCADOR_PROJETO[d.nota.projetoId]],
    temLacunaInformacao: temLacuna,
    chaveCobranca: d.perfil.retranca + '_L' + d.nota.linha,
    // Uma linha da planilha por bloco — o consolidador grava coluna N/L em todas elas.
    linhasAfetadas: grupo.map((l) => ({ projetoId: l.nota.projetoId, linha: l.nota.linha, atualizarColunaNPara: l.atualizarColunaNPara })),
  } });
}

return saida;

// Agrupa linhas FORNECEDOR (mesmo projeto+fornecedor+vencimento) e monta 1 e-mail
// multi-bloco por grupo (secao 3.2.1). Roda 1x pra TODOS os itens fornecedor da execucao
// (mode = runOnceForAllItems).
//
// NOVO (secao 3.2.1, fechamento): o gate de contrato acontece por GRUPO, nao por linha.
// Se qualquer linha do grupo tiver liberado=true, o grupo inteiro e tratado como liberado,
// as linhas que nao tinham coluna N = OK-ASSINADO sao corrigidas, e um aviso extra e
// enviado pro Telegram avisando a correcao (fornecedor + valor da nota corrigida).

const MESES_ABREV_PT = ['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];
const MARCADOR_PROJETO = { REUNION: 'REUNION - PEDIDO DE NOTAS', SOFT_PRE: 'SOFT PRE - PEDIDO NOTAS', AREP: 'AREP - PEDIDO DE NOTAS' };
const TOMADOR_HTML = '<p><b>Tomador</b><br>\n' +
  'BOXFISH PRODUTORA DE PROGRAMAS TELEVISIVOS, INTERNET E FILMES PUBLICITÁRIOS LTDA.<br>\n' +
  'Endereço: Rua Butantã, 194, sala 24, Pinheiros.<br>\n' +
  'CEP 05.424-000 - São Paulo, SP<br>\n' +
  'CNPJ: 14.788.649/0001-23<br>\n' +
  'IM: 4.436.095-9<br>\n' +
  'IE: ISENTA</p>';
const AVISO_HTML = '<p><i>"Os dados bancários considerados para pagamento são os que estão cadastrados.<br>\n' +
  'O cadastro é feito baseado nas informações cedidas pelo contratado através do preenchimento de ficha cadastral da Box.<br>\n' +
  'Qualquer alteração bancária ou mudança na forma de pagamento deve ser notificada por e-mail pelo contratado e se faz necessário atualização da ficha cadastral e envio prévio ao responsável financeiro do projeto."</i></p>' +
  '\n<p>Muito obrigada!<br>\nBjs 🌷</p>';
const IMPORTANTE_HTML = '<p><b><span style="color:#FF0000;">Importante: Peço a gentileza de enviar a sua nota nestes e-mails:</span></b><br>\n' +
  'financeiro@novorealitybox.com<br>\nfinanceiro1@novorealitybox.com</p>';
const EMAIL_TESTE_HOMOLOG = 'grandesnegocioseoportunidades+colaborador@gmail.com';
// Cópia (CC) por ambiente — seção 3.1.7. Em homolog vai pro endereço de teste da
// Danielle; em produção, pro e-mail real da controller. O destinatário principal
// segue a mesma lógica: fixo de teste em homolog, coluna R em produção.
const EMAIL_COPIA_HOMOLOG = 'grandesnegocioseoportunidades+danielle@gmail.com';
const EMAIL_COPIA_PRODUCAO = 'financeiro@novorealitybox.com';

// ─── Formatação do e-mail — valores EXATOS da seção 3.5 do spec, extraídos de um e-mail
// real de produção. Vale igual em homolog: o e-mail de teste tem que ser visualmente
// idêntico ao de produção, mudando só destinatário e credencial (seções 7.4 e 3.5).
const FONTE_EMAIL = 'Verdana, Geneva, sans-serif';
const COR_DATA_ENVIO = '#cc0000';      // só a data do "enviada até o dia" — em negrito (3.5)
const FUNDO_VENCIMENTO = '#CFE2F3';    // só os números da data de vencimento
const FUNDO_BLOCO_EMITIR = '#FFE599';  // bloco "N- Emitir ... no valor de R$ X"
const COR_IMPORTANTE = '#FF0000';      // "Importante: Peço a gentileza..."

function envolverCorpo(partes) {
  return '<div style="font-family:' + FONTE_EMAIL + ';">\n' + partes.filter(Boolean).join('\n') + '\n</div>';
}

// "...enviada até o dia DD/MM" -> cor só na data. "vencimento em DD/MM/AAAA." -> negrito no
// trecho inteiro, com highlight só nos números da data.
// Abertura por tipo de documento do e-mail:
//   'recibo_e_nf' -> fornecedor REC+NF (dois documentos, seção 3.2.1)
//   'fatura'      -> fornecedor só RECIBO. NUNCA "nota fiscal" aqui: locação se cobra por
//                    recibo/fatura, e trocar a palavra é erro fiscal (seção 3.2).
//   'varias_nf'   -> colaborador com mais de um bloco -> plural (seção 3.2.1)
//   'uma_nf'      -> colaborador com um bloco só
function paragrafoAbertura(dataEnvio, dataVencimento, tipoAbertura) {
  const VERBOS = {
    recibo_e_nf: 'Seguem as instruções para a emissão do RECIBO e da NOTA FISCAL que deverão ser enviadas ',
    fatura: 'Seguem as instruções para a emissão da sua FATURA que deverá ser enviada ',
    varias_nf: 'Seguem as instruções para a emissão das suas notas fiscais que deverão ser enviadas ',
    uma_nf: 'Seguem as instruções para a emissão da sua nota fiscal que deverá ser enviada ',
  };
  const verbo = VERBOS[tipoAbertura] || VERBOS.uma_nf;
  // "até o dia DD/MM" INTEIRO em vermelho; só os números da data em negrito (3.5).
  const ateODia = '<span style="color:' + COR_DATA_ENVIO + ';"><b>até o dia ' + formatarDataDiaMes(dataEnvio) + '</b></span>';
  // "vencimento em DD/MM/AAAA." INTEIRO com o highlight; o ponto final fica DENTRO do
  // highlight e FORA do negrito (3.5).
  const vencimento = '<span style="background-color:' + FUNDO_VENCIMENTO + ';">' +
    '<b>vencimento em ' + formatarDataBR(dataVencimento) + '</b>.</span>';
  return '<p>' + verbo + ateODia + ' com ' + vencimento + '</p>';
}

function blocoEmitir(numero, textoDocumento, valor) {
  const valorFmt = valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return '<p><span style="background-color:' + FUNDO_BLOCO_EMITIR + ';">' + numero +
    '- Emitir ' + textoDocumento + ' no valor de <b>R$ ' + valorFmt + '</b> com os dados abaixo no corpo da nota:</span></p>';
}

function blocoDadosBancarios() {
  // Sem <p> vazio entre "Período de" e "Dados bancários": a 3.5 (referência Paulo Bento)
  // pede parágrafos sequenciais, com o espaçamento vindo só da margem padrão do <p>.
  return '<p><b>Dados bancários:</b></p>\n<p><b>Chave pix:</b></p>\n' +
    '<p>---------------------------------------------------------------------</p>';
}

// ─── Período em ordem cronológica ASCENDENTE (spec 3.2.1) ───
// A planilha às vezes traz as datas invertidas por erro de digitação ("05/08 A 26/07") e o
// e-mail não pode reproduzir isso.
//
// Sem ano na origem, "26/12 A 05/01" é virada de ano legítima, não inversão. Das duas
// leituras possíveis escolhemos a de PERÍODO MAIS CURTO — período de trabalho tem dias ou
// semanas: 26/12→05/01 dá 10 dias e vence 05/01→26/12, que daria 355; e o par de fato
// invertido "05/08 A 26/07" é corrigido pelo mesmo critério, sem regra especial.
function diasEntre(diaA, mesA, diaB, mesB) {
  const ini = Date.UTC(2001, mesA - 1, diaA);
  let fim = Date.UTC(2001, mesB - 1, diaB);
  if (fim < ini) fim = Date.UTC(2002, mesB - 1, diaB); // virou o ano
  return (fim - ini) / 86400000;
}

function normalizarPeriodo(periodo) {
  const txt = String(periodo || '');
  const datas = txt.match(/\d{1,2}\s*\/\s*\d{1,2}/g);
  if (!datas || datas.length < 2) return txt;
  const [a, b] = datas;
  const pa = a.split('/').map((x) => parseInt(x, 10));
  const pb = b.split('/').map((x) => parseInt(x, 10));
  const comoEscrito = diasEntre(pa[0], pa[1], pb[0], pb[1]);
  const invertido = diasEntre(pb[0], pb[1], pa[0], pa[1]);
  if (invertido >= comoEscrito) return txt;
  let n = 0;
  return txt.replace(/\d{1,2}\s*\/\s*\d{1,2}/g, () => (n++ === 0 ? b : a));
}

// Meses citados por um período. Um período que atravessa a virada do mês devolve OS DOIS
// (spec 3.2.1) — não escolhe um. Já vem em ordem cronológica, porque roda sobre o período
// normalizado.
function mesesDoPeriodo(periodo) {
  const datas = String(periodo || '').match(/\d{1,2}\s*\/\s*\d{1,2}/g) || [];
  const meses = [];
  for (const d of datas) {
    const mes = parseInt(d.split('/')[1], 10);
    if (mes >= 1 && mes <= 12) {
      const nome = MESES_ABREV_PT[mes - 1];
      if (meses.indexOf(nome) === -1) meses.push(nome);
    }
  }
  return meses;
}

function normalizar(t) { return t ? String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim() : ''; }
function formatarDataBR(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear(); }
// Data do "ate o dia" no CORPO: DD/MM, sem ano — formato diferente do vencimento
// (DD/MM/AAAA), de proposito (3.5, confirmado com e-mail padrao de producao).
// Nao confundir com formatarDataCurta, que e DD.MM com PONTO e vale pro ASSUNTO.
function formatarDataDiaMes(d) { return String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0'); }
function formatarDataCurta(d) { return String(d.getDate()).padStart(2,'0') + '.' + String(d.getMonth()+1).padStart(2,'0'); }
// O apelido de projeto (apelidos.json) e so o identificador: "AREP", "SMTC - S01 | REUNION".
// Ja o prefixo_assunto_pedido do perfil vem com "| EMISSAO DE NF" embutido (spec secao 6).
// Como o assunto concatena a palavra do documento logo depois, usar o prefixo cru no
// fallback duplicava o trecho ("... | EMISSAO DE NF | EMISSAO DE NF | REF. ..."). Nao
// aparecia em execucao porque hoje o apelidos.json cobre os 3 projetos e o fallback nunca
// roda — mas passaria a aparecer se um projeto sumisse do arquivo.
function apelidoDoPerfil(perfil) {
  return String((perfil && perfil.prefixo_assunto_pedido) || '')
    .replace(/\s*\|\s*EMISS[ÃA]O DE .*$/i, '')
    .trim();
}
function ehModoAutomatico(config) { return config && config.modo === 'automatico'; }
// Status Box que ainda representam "antes do envio". Só esses podem virar "SOLICITADA MI"
// (spec 3.1.8): se a linha ja avancou (ENTREGUE MI, ENTREGUE MI R1...), a automacao nao pode
// regredir um estagio alcancado manualmente.
function statusBoxAindaAntesDoEnvio(statusBox) {
  const s = String(statusBox || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();
  return /^PROGRAMAR ATE/.test(s) || /^SOLICITAR/.test(s);
}

// Compara so a data do calendario, ignorando hora.
function chegouNaDataAlvo(dataAlvoISO, hoje) {
  if (!dataAlvoISO) return true;
  const alvoYMD = String(dataAlvoISO).slice(0, 10);
  const hojeYMD = new Date(hoje.getTime() - hoje.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  return hojeYMD >= alvoYMD;
}

function decidirAcaoEnvio(gatilho, modoAutomatico, forcarRascunho, contexto) {
  // "SOLICITAR / AGUARDAR DOCS" (escala 5) SEMPRE fica em rascunho, mesmo em
  // MODO_EXECUCAO=automatico e ambiente producao — unica excecao do sistema (secao 3.1.4).
  // O flag vem pronto do node de filtro: nao reinterpretamos o Status Box aqui, pra que a
  // excecao nao possa vazar pra outras variantes.
  if (forcarRascunho) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };

  // ── PROGRAMAR ATE (spec 3.1.8) ──────────────────────────────────────────────
  // A API do Gmail nao tem envio agendado — isso so existe na interface web. O contorno e
  // criar o rascunho desde ja e enviar numa execucao do dia do prazo.
  if (gatilho === 'PROGRAMAR_ATE') {
    const ctx = contexto || {};
    const rascunhoGuardado = ctx.estado && ctx.estado.draftId;

    // ainda nao existe rascunho -> cria agora. Coluna L NAO muda (item 2 da 3.1.8).
    if (!rascunhoGuardado) {
      return { acaoGmail: 'criar_rascunho', atualizarColunaL: false, programado: true };
    }
    // ja existe rascunho e a data nao chegou -> nao faz nada, nao duplica (item 3)
    if (!chegouNaDataAlvo(ctx.dataAlvo, ctx.hoje)) {
      return { acaoGmail: 'aguardando_data', atualizarColunaL: false };
    }
    // chegou a data, mas modo rascunho nunca envia sozinho (item 4)
    if (!modoAutomatico) {
      return { acaoGmail: 'aguardando_revisao_manual', atualizarColunaL: false };
    }
    // chegou a data em modo automatico -> o ramo de envio checa se o rascunho existe.
    // Coluna L fica false AQUI de proposito: quem decide grava-la e o ramo, depois de
    // confirmar o envio (spec 3.1.5).
    return { acaoGmail: 'enviar_programado', atualizarColunaL: false, draftIdProgramado: ctx.estado.draftId };
  }

  if (!modoAutomatico) return { acaoGmail: 'criar_rascunho', atualizarColunaL: false };
  return { acaoGmail: 'enviar_direto', atualizarColunaL: true, novoValorColunaL: 'SOLICITADA MI' };
}
function agruparLinhasFornecedor(itens) {
  const grupos = new Map();
  for (const item of itens) {
    const chave = [item.nota.projetoId, normalizar(item.nota.colunaH), item.nota.colunaG].join('|');
    if (!grupos.has(chave)) grupos.set(chave, []);
    grupos.get(chave).push(item);
  }
  return Array.from(grupos.values());
}
function ordenarBlocosGrupo(grupo) {
  const recibos = grupo.filter((i) => i.documentoLinha === 'RECIBO');
  const notas = grupo.filter((i) => i.documentoLinha === 'NOTA_FISCAL');
  const semClassificacao = grupo.filter((i) => i.documentoLinha !== 'RECIBO' && i.documentoLinha !== 'NOTA_FISCAL');
  return { blocosOrdenados: [...recibos, ...notas], semClassificacao };
}
function montarBlocoRecibo(numero, item, textoRef) {
  return [
    blocoEmitir(numero, 'RECIBO', item.nota.colunaK),
    '<p>Ref. "' + textoRef + '"</p>',
    '<p><b>Fornecedor:</b> ' + item.nota.colunaH + '</p>',
    '<p><b>Período de</b> ' + normalizarPeriodo(item.periodo) + ' - ' + item.descricaoServicoOuLocacao + '</p>',
    blocoDadosBancarios(),
  ].join('\n');
}
function montarBlocoNotaFiscal(numero, item, textoRef) {
  return [
    blocoEmitir(numero, 'NOTA FISCAL', item.nota.colunaK),
    '<p>Ref. "' + textoRef + '"</p>',
    '<p><b>Fornecedor:</b> ' + item.nota.colunaH + '</p>',
    '<p><b>Serviço Prestado:</b> ' + item.descricaoServicoOuLocacao + '</p>',
    '<p><b>Período de</b> ' + normalizarPeriodo(item.periodo) + '</p>',
    blocoDadosBancarios(),
  ].join('\n');
}
function montarCorpoEmailFornecedor({ blocosOrdenados, temNotaFiscal, dataEnvio, dataVencimento, textoRef }) {
  const blocos = blocosOrdenados.map((item, idx) => item.documentoLinha === 'RECIBO'
    ? montarBlocoRecibo(idx + 1, item, textoRef)
    : montarBlocoNotaFiscal(idx + 1, item, textoRef));
  return envolverCorpo([
    '<p>Olá! Tudo bem? 😊</p>',
    paragrafoAbertura(dataEnvio, dataVencimento, temNotaFiscal ? 'recibo_e_nf' : 'fatura'),
    TOMADOR_HTML,
    blocos.join('\n'),
    IMPORTANTE_HTML,
    AVISO_HTML,
  ]);
}
function montarAssuntoFornecedor({ apelidoAtual, temNotaFiscal, parcela, dataEnvio, fornecedor }) {
  const mes = MESES_ABREV_PT[dataEnvio.getMonth()];
  const palavraDocumento = temNotaFiscal ? 'EMISSÃO DE FATURA' : 'EMISSÃO DE RECIBO';
  const ref = temNotaFiscal ? ('REF. LOCAÇÃO E SERVIÇOS - ' + mes) : ('REF. LOCAÇÃO - ' + mes + (parcela ? (' - ' + parcela) : ''));
  return apelidoAtual + ' | ' + palavraDocumento + ' | ' + ref + ' | (ENVIAR ATÉ ' + formatarDataCurta(dataEnvio) + ') | ' + fornecedor;
}

const hoje = new Date();
const itens = $input.all().map((i) => i.json);
const grupos = agruparLinhasFornecedor(itens);
const saida = [];

for (const grupo of grupos) {
  const { blocosOrdenados, semClassificacao } = ordenarBlocosGrupo(grupo);

  if (semClassificacao.length > 0) {
    saida.push({ json: { ...semClassificacao[0], acao: 'alerta_situacao_nao_mapeada', situacaoNaoMapeada: 'Não foi possível classificar RECIBO/NOTA_FISCAL para ' + semClassificacao.length + ' linha(s) do fornecedor ' + grupo[0].nota.colunaH } });
    continue;
  }
  if (blocosOrdenados.length === 0) continue;

  // Gate de contrato POR GRUPO (secao 3.2.1, fechamento): se qualquer linha liberada, grupo inteiro libera.
  const algumaLiberada = blocosOrdenados.some((b) => b.liberado);
  if (!algumaLiberada) {
    saida.push({ json: { ...blocosOrdenados[0], acao: 'pendente_contrato' } });
    continue;
  }
  const linhasCorrigidas = blocosOrdenados.filter((b) => !b.liberado);

  const primeiro = blocosOrdenados[0];
  // Deduplicação do pedido (3.1.6) — SÓ em produção. Ver comentário equivalente no node
  // "Montar e-mail colaborador". No caso de fornecedor a chave é a da PRIMEIRA linha do
  // grupo, que é exatamente a que o fluxo grava em cobrancas.json para o grupo.
  const chaveDedup = primeiro.perfil.retranca + '_L' + primeiro.nota.linha;
  const entradaAnterior = (primeiro.cobrancas || {})[chaveDedup];
  if (primeiro.config && primeiro.config.ambiente === 'producao' && entradaAnterior && entradaAnterior.threadId) {
    saida.push({ json: { ...primeiro, acao: 'pedido_ja_criado', chaveCobranca: chaveDedup, threadIdExistente: entradaAnterior.threadId } });
    continue;
  }

  const temNotaFiscal = blocosOrdenados.some((b) => b.documentoLinha === 'NOTA_FISCAL');
  const dataVencimento = new Date(primeiro.nota.colunaG);
  const dataBase = primeiro.gatilho === 'PROGRAMAR_ATE' ? new Date(primeiro.dataProgramarAte) : hoje;
  const dataEnvio = primeiro.gatilho === 'PROGRAMAR_ATE' ? (function(){ const dd = new Date(dataBase); dd.setDate(dd.getDate()+5); return dd; })() : dataBase;
  const apelidoAtual = (primeiro.apelidos && primeiro.apelidos[primeiro.nota.projetoId] && primeiro.apelidos[primeiro.nota.projetoId].length) ? primeiro.apelidos[primeiro.nota.projetoId][primeiro.apelidos[primeiro.nota.projetoId].length - 1] : apelidoDoPerfil(primeiro.perfil);

  const corpo = montarCorpoEmailFornecedor({ blocosOrdenados, temNotaFiscal, dataEnvio, dataVencimento, textoRef: primeiro.perfil.texto_ref });
  let assunto = montarAssuntoFornecedor({ apelidoAtual, temNotaFiscal, parcela: primeiro.parcela, dataEnvio, fornecedor: primeiro.nota.colunaH });
  if (primeiro.escalaUrgencia === 0) assunto = 'URG | ' + assunto;

  // Ambiente troca APENAS destinatario e credencial (spec 7.4 e 3.5) — sem marca de
  // ambiente no assunto nem no corpo. Ver comentario no "Montar e-mail colaborador".
  const ehHomolog = primeiro.config && primeiro.config.ambiente === 'homolog';
  const emailDestino = ehHomolog ? EMAIL_TESTE_HOMOLOG : primeiro.nota.colunaR;
  const emailCopia = ehHomolog ? EMAIL_COPIA_HOMOLOG : EMAIL_COPIA_PRODUCAO;

  const decisao = decidirAcaoEnvio(primeiro.gatilho, ehModoAutomatico(primeiro.config), primeiro.forcarRascunho, {
    estado: (primeiro.cobrancas || {})[primeiro.perfil.retranca + '_L' + primeiro.nota.linha],
    dataAlvo: primeiro.dataProgramarAte,
    hoje,
  });

  saida.push({ json: {
    ...primeiro,
    acao: decisao.acaoGmail,
    // PROGRAMAR ATE: viaja junto pro node que grava cobrancas.json (3.1.8)
    dataAlvoEnvio: decisao.programado ? primeiro.dataProgramarAte : undefined,
    draftIdProgramado: decisao.draftIdProgramado,
    atualizarColunaL: decisao.atualizarColunaL,
    novoValorColunaL: decisao.novoValorColunaL,
    emailDestino,
    emailCopia,
    assunto,
    corpoHtml: corpo,
    marcadores: ['IA', MARCADOR_PROJETO[primeiro.nota.projetoId]],
    chaveCobranca: primeiro.perfil.retranca + '_L' + primeiro.nota.linha,
    linhasAfetadas: blocosOrdenados.map((b) => ({ projetoId: b.nota.projetoId, linha: b.nota.linha, atualizarColunaNPara: b.liberado ? b.atualizarColunaNPara : 'OK - ASSINADO' })),
  } });

  if (linhasCorrigidas.length > 0) {
    saida.push({ json: {
      acao: 'avisar_correcao_contrato',
      fornecedor: primeiro.nota.colunaH,
      linhasCorrigidas: linhasCorrigidas.map((b) => ({ linha: b.nota.linha, valor: b.nota.colunaK })),
    } });
  }
}

return saida;

// Avalia cobranca para linhas ja SOLICITADA MI (fluxo='monitoramento') - secao 3.1.1.
// Schema de cobrancas.json ALINHADO ao spec.md: threadId, data_ultima_cobranca,
// contagem_cobrancas, status_ciclo ('em_andamento'|'encerrado_sem_resposta'|'recebido').
function somarDias(data, dias) { const d = new Date(data); d.setDate(d.getDate() + dias); return d; }
function diferencaDias(a, b) { const MS = 86400000; const u1 = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate()); const u2 = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate()); return Math.round((u1 - u2) / MS); }
function avaliarCobranca({ hoje, dataProgramarAte, dataVencimentoNF, estadoAtual }) {
  if (estadoAtual && estadoAtual.status_ciclo && estadoAtual.status_ciclo !== 'em_andamento') return { acao: 'nenhuma' };
  const fimDoCiclo = somarDias(dataVencimentoNF, -5);
  if (diferencaDias(hoje, dataProgramarAte) < 0) return { acao: 'nenhuma' };
  if (diferencaDias(hoje, fimDoCiclo) >= 0) {
    return { acao: 'encerrar_sem_resposta', novoEstado: { threadId: estadoAtual ? estadoAtual.threadId : null, data_ultima_cobranca: estadoAtual ? estadoAtual.data_ultima_cobranca : null, contagem_cobrancas: estadoAtual ? estadoAtual.contagem_cobrancas : 0, status_ciclo: 'encerrado_sem_resposta' } };
  }
  if (!estadoAtual) return { acao: 'nenhuma' }; // sem entrada em cobrancas.json ainda (threadId deveria ter sido gravado na criacao do pedido) - nada a fazer até existir.
  if (estadoAtual.contagem_cobrancas === 0) {
    const diaPrimeira = somarDias(dataProgramarAte, 1);
    if (diferencaDias(hoje, diaPrimeira) >= 0) {
      return { acao: 'cobrar', novoEstado: { threadId: estadoAtual.threadId, data_ultima_cobranca: hoje.toISOString().slice(0,10), contagem_cobrancas: 1, status_ciclo: 'em_andamento' } };
    }
    return { acao: 'nenhuma' };
  }
  const dataUltima = new Date(estadoAtual.data_ultima_cobranca);
  if (diferencaDias(hoje, dataUltima) >= 5) {
    return { acao: 'cobrar', novoEstado: { threadId: estadoAtual.threadId, data_ultima_cobranca: hoje.toISOString().slice(0,10), contagem_cobrancas: estadoAtual.contagem_cobrancas + 1, status_ciclo: 'em_andamento' } };
  }
  return { acao: 'nenhuma' };
}

const hoje = new Date();
return $input.all().map((item) => {
  const d = item.json;
  const vencimento = new Date(d.nota.colunaG);
  const chaveCobranca = d.perfil.retranca + '_L' + d.nota.linha;
  const estadoAtual = d.cobrancas ? d.cobrancas[chaveCobranca] : undefined;
  const dataProgramarAte = estadoAtual && estadoAtual.dataProgramarAteOriginal ? new Date(estadoAtual.dataProgramarAteOriginal) : hoje;
  const resultado = avaliarCobranca({ hoje, dataProgramarAte, dataVencimentoNF: vencimento, estadoAtual });
  const acao = resultado.acao === 'cobrar' ? (d.config.modo === 'automatico' ? 'cobrar_enviar' : 'cobrar_rascunho') : resultado.acao;
  return { json: { ...d, acao, chaveCobranca, novoEstadoCobranca: resultado.novoEstado, threadId: estadoAtual ? estadoAtual.threadId : null } };
});

// Consolida: (a) mudancas de coluna N/L a escrever no Box, (b) novo cobrancas.json,
// (c) resumo pro relatorio (incl. lacunas de informacao, correcoes de contrato e alertas
// de situacao nao mapeada), (d) registro no log diario pro /resumo (secao 7.3).
// Suporta itens de 1 linha (colaborador/cobranca/pendente) e itens de GRUPO fornecedor
// (varias linhas por item, campo linhasAfetadas — secao 3.2.1).

const itens = $input.all().map((i) => i.json);

const mudancasColunaN = [];
const mudancasColunaL = [];

for (const d of itens) {
  if (Array.isArray(d.linhasAfetadas)) {
    for (const la of d.linhasAfetadas) {
      if (la.atualizarColunaNPara) mudancasColunaN.push({ projetoId: la.projetoId, linha: la.linha, valor: la.atualizarColunaNPara });
      if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: la.projetoId, linha: la.linha, valor: d.novoValorColunaL });
    }
    continue;
  }
  if (d.atualizarColunaNPara) mudancasColunaN.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.atualizarColunaNPara });
  if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.novoValorColunaL });
}

const cobrancasAtualizadas = { ...(itens.find((d) => d.cobrancas) ? itens.find((d) => d.cobrancas).cobrancas : {}) };
for (const d of itens) {
  if (d.chaveCobranca && d.novoEstadoCobranca) cobrancasAtualizadas[d.chaveCobranca] = d.novoEstadoCobranca;
}

const alertasEncerramento = itens.filter((d) => d.acao === 'encerrar_sem_resposta');
const alertasSituacaoNaoMapeada = itens.filter((d) => d.acao === 'alerta_situacao_nao_mapeada');
const correcoesContrato = itens.filter((d) => d.acao === 'avisar_correcao_contrato');
const rascunhosCriados = itens.filter((d) => d.acao === 'criar_rascunho' || d.acao === 'cobrar_rascunho');
const enviosDiretos = itens.filter((d) => d.acao === 'enviar_direto' || d.acao === 'cobrar_enviar');
const pendentesContrato = itens.filter((d) => d.acao === 'pendente_contrato');
const comLacunaInformacao = itens.filter((d) => d.temLacunaInformacao);

const resumo = {
  rascunhosCriados: rascunhosCriados.length,
  enviosDiretos: enviosDiretos.length,
  pendentesContrato: pendentesContrato.length,
  comLacunaInformacao: comLacunaInformacao.length,
  alertasSituacaoNaoMapeada: alertasSituacaoNaoMapeada.length,
  correcoesContrato: correcoesContrato.length,
  alertasEncerramento: alertasEncerramento.map((a) => ({ colaboradorOuFornecedor: a.nomeColaborador || (a.nota && a.nota.colunaH), projetoId: a.nota && a.nota.projetoId })),
};

return [{ json: {
  mudancasColunaN, mudancasColunaL, cobrancasAtualizadas, resumo,
  logEntry: { timestamp: new Date().toISOString(), fase: 'fase1_solicitacao_nota', resumo },
} }];

// Acrescenta o resumo desta execucao ao log diario (secao 7.3) — lido por
// workflows/resumo_diario.json. Mantem só os últimos 30 dias pra não crescer sem limite
// (não especificado no spec.md — escolha de implementação razoável, fácil de ajustar).
// Leitura de binário: esta instância do n8n guarda binário no disco (filesystem-v2),
// então item.binary.data.data NÃO é o conteúdo, e sim o rótulo do modo de armazenamento.
// O único acesso liberado no Code Node é helpers.getBinaryDataBuffer, que lê pelo ÍNDICE
// do item no input DIRETO — por isso "Ler log_diario.json" alimenta este node diretamente.
let log = [];
try {
  const b = $input.first().binary;
  if (b && b.data) {
    const buf = b.data.id ? await this.helpers.getBinaryDataBuffer(0, 'data') : Buffer.from(b.data.data, 'base64');
    log = JSON.parse(buf.toString('utf8'));
  }
} catch (e) { log = []; } // 1a execução: arquivo ainda não existe
log.push($('Consolidar mudanças e cobrancas.json').first().json.logEntry);
const LIMITE_DIAS = 30;
const corte = new Date(); corte.setDate(corte.getDate() - LIMITE_DIAS);
log = log.filter((e) => new Date(e.timestamp) >= corte);
return [{ json: {}, binary: { data: { data: Buffer.from(JSON.stringify(log, null, 2)).toString('base64'), mimeType: 'application/json', fileName: 'log_diario__SUFIXO_AMBIENTE__.json' } } }];

// Monta a 1a entrada de cobrancas.json (secao 3.1.1: "o threadId e gravado assim que o
// e-mail de pedido e criado"). O payload e o threadId ja vem casados do node anterior,
// entao aqui o indice e dentro da propria ramificacao — 1:1, sem risco de trocar item.
const pedidos = $('Casar resposta do Gmail (rascunho pedido)').all();

return $input.all().map((item, i) => {
  const d = (pedidos[i] || {}).json || {};
  const hoje = new Date();
  return { json: {
    ...d,
    novoEstadoCobranca: {
      threadId: d.threadIdGmail || null,
      // PROGRAMAR ATE (3.1.8): o rascunho foi criado antes da data-alvo; guardamos o id e a
      // data pra saber, nas proximas execucoes, que ja existe rascunho e quando envia-lo.
      draftId: d.draftId || null,
      dataAlvoEnvio: d.dataAlvoEnvio || null,
      data_ultima_cobranca: hoje.toISOString().slice(0, 10),
      contagem_cobrancas: 0,
      status_ciclo: 'em_andamento',
    },
  } };
});

// Monta a 1a entrada de cobrancas.json (secao 3.1.1: "o threadId e gravado assim que o
// e-mail de pedido e criado"). O payload e o threadId ja vem casados do node anterior,
// entao aqui o indice e dentro da propria ramificacao — 1:1, sem risco de trocar item.
const pedidos = $('Casar resposta do Gmail (envio pedido)').all();

return $input.all().map((item, i) => {
  const d = (pedidos[i] || {}).json || {};
  const hoje = new Date();
  return { json: {
    ...d,
    novoEstadoCobranca: {
      threadId: d.threadIdGmail || null,
      data_ultima_cobranca: hoje.toISOString().slice(0, 10),
      contagem_cobrancas: 0,
      status_ciclo: 'em_andamento',
    },
  } };
});

