// Monta o mapa nome -> id dos marcadores do Gmail.
// Usado pelos nodes 'Gmail — Aplicar marcadores (...)', porque a API
// aceita só ID de marcador, e o spec.md (3.1.2) define os marcadores por NOME.
const mapa = {};
for (const item of $input.all()) {
  const l = item.json;
  if (l && l.name && l.id) mapa[l.name] = l.id;
}
const esperados = ['IA', 'REUNION - PEDIDO DE NOTAS', 'SOFT PRE - PEDIDO NOTAS', 'AREP - PEDIDO DE NOTAS', 'CONTRATAÇÃO'];
const faltando = esperados.filter((n) => !mapa[n]);
// Não interrompe a execução: marcador faltando é problema de cadastro no Gmail,
// não motivo pra travar o pedido de nota. Fica registrado pro relatório.
return [{ json: { mapa, marcadoresFaltando: faltando } }];

// A resposta do addLabels nao carrega os campos que o consolidador usa (acao,
// chaveCobranca, novoEstadoCobranca...). Restaura o payload ja casado no node anterior —
// indice dentro da propria ramificacao, 1:1.
const pedidos = $('Casar resposta do Gmail (cobrança rascunho)').all();
return $input.all().map((item, i) => ({ json: (pedidos[i] || {}).json || {} }));

// A resposta do addLabels nao carrega os campos que o consolidador usa (acao,
// chaveCobranca, novoEstadoCobranca...). Restaura o payload ja casado no node anterior —
// indice dentro da propria ramificacao, 1:1.
const pedidos = $('Casar resposta do Gmail (cobrança envio)').all();
return $input.all().map((item, i) => ({ json: (pedidos[i] || {}).json || {} }));

// Ponto de partida das duas checagens paralelas (spec 3.1). Existe por dois motivos:
// dar um ponto de ramificação explícito, e servir de referência estável — o node da ficha
// cadastral precisa mapear cada mensagem do Gmail de volta pra linha que a originou.
return $input.all();

// Checagem A das duas paralelas (spec 3.1): cruzamento com a planilha de Contratos.
// Criterio LITERAL "ASSINADO" no status — qualquer outro valor ("E A dd/mm", vazio,
// "AGUARDANDO ASSINATURA DO CONTRATO"...) nao confirma.
//
// A CORRESPONDENCIA DE NOME e tolerante a variacao de grafia (spec 3.1, 27/08), em camadas:
//   1. documento (CPF/CNPJ) nos dois lados -> confirmacao definitiva
//   2. nome por token: PRIMEIRO e ULTIMO token batendo (distancia de edicao <= 1)
//   3. mais de um candidato distinto -> NAO libera, marca ambiguidade pro alerta
//   4. nenhum candidato -> pendente
//
// O item 2 e o que impede falso positivo: exigir primeiro E ultimo token exclui
// "GUILHERME HENRIQUE PORTES SIQUEIRA" e "BRUNA GUILHERME COUTO" de "GUILHERME BRUM"
// automaticamente, sem precisar de lista de excecao.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function contratoAssinadoNaPlanilha(status) {
  return normalizar(status) === 'assinado';
}

// Nesta base o documento vem colado ao nome, no formato XX.XXX.XXX (8 digitos, raiz de
// CNPJ/MEI): "56.240.209 ELIANA AMRAL JORGE". Aceita tambem CPF/CNPJ completos.
function digitosDeDocumento(texto) {
  const m = String(texto || '').match(/\d[\d.\-/]{7,}/);
  if (!m) return null;
  const d = m[0].replace(/\D/g, '');
  return d.length >= 8 ? d : null;
}

function documentosBatem(a, b) {
  if (!a || !b) return false;
  if (a === b) return true;
  // um lado pode trazer o documento completo e o outro so a raiz
  const curto = a.length <= b.length ? a : b;
  const longo = a.length <= b.length ? b : a;
  return curto.length >= 8 && longo.indexOf(curto) === 0;
}

// Distancia de edicao <= 1 (insercao, remocao ou substituicao de 1 caractere).
// Casa os prefixos e sufixos iguais e ve o que sobra no meio.
function distanciaAte1(a, b) {
  if (a === b) return true;
  const dif = Math.abs(a.length - b.length);
  if (dif > 1) return false;
  const curta = a.length <= b.length ? a : b;
  const longa = a.length <= b.length ? b : a;
  let i = 0;
  while (i < curta.length && curta[i] === longa[i]) i++;
  let j = 0;
  while (j < curta.length - i && curta[curta.length - 1 - j] === longa[longa.length - 1 - j]) j++;
  // tamanhos diferentes -> insercao/remocao: a palavra curta tem que ser coberta inteira.
  // tamanhos iguais -> substituicao: pode sobrar exatamente 1 caractere sem casar.
  return i + j >= curta.length - (dif === 0 ? 1 : 0);
}

function tokensDoNome(nome) {
  // tira o documento do inicio, se houver, e fica so com as palavras do nome
  return normalizar(String(nome || '').replace(/^[\d.\-/\s]+/, '')).split(' ').filter(Boolean);
}

// Primeiro e ultimo token precisam bater. Nomes do meio podem faltar, sobrar ou diferir.
// Nome de 1 token so casa com outro de 1 token: sem sobrenome nao da pra confirmar pessoa.
function nomesBatem(a, b) {
  const ta = tokensDoNome(a);
  const tb = tokensDoNome(b);
  if (!ta.length || !tb.length) return false;
  return distanciaAte1(ta[0], tb[0]) && distanciaAte1(ta[ta.length - 1], tb[tb.length - 1]);
}

function cruzarComPlanilhaContratos(nota, nomeDaIA, linhasContratos) {
  const linhas = linhasContratos || [];
  const docCost = digitosDeDocumento(nota.colunaH);
  // o nome vem da IA (spec 3.2); colunaH e so fallback se a IA nao tiver extraido
  const nomeCost = nomeDaIA && nomeDaIA !== 'FALTA INFORMACAO' && nomeDaIA !== 'FALTA INFORMAÇÃO'
    ? nomeDaIA
    : nota.colunaH;

  // camada 1 — documento nos dois lados
  const porDocumento = linhas.filter((l) => documentosBatem(docCost, digitosDeDocumento(l.razaoSocial)));
  if (porDocumento.length) {
    return {
      confirmado: porDocumento.some((l) => contratoAssinadoNaPlanilha(l.status)),
      criterio: 'documento',
      candidatos: porDocumento.map((l) => l.nomeColaborador || l.razaoSocial),
    };
  }

  // camada 2 — nome por token
  const porNome = linhas.filter((l) => nomesBatem(nomeCost, l.nomeColaborador) || nomesBatem(nomeCost, l.razaoSocial));
  if (!porNome.length) return { confirmado: false, criterio: 'sem_candidato', candidatos: [] };

  // camada 3 — ambiguidade: mais de uma PESSOA distinta batendo
  const identidades = {};
  for (const l of porNome) {
    const chave = normalizar(l.nomeColaborador) || normalizar(l.razaoSocial);
    if (!identidades[chave]) identidades[chave] = [];
    identidades[chave].push(l);
  }
  const chaves = Object.keys(identidades);
  if (chaves.length > 1) {
    return {
      confirmado: false,
      criterio: 'ambiguidade',
      candidatos: porNome.map((l) => (l.nomeColaborador || l.razaoSocial) + ' [' + (l.status || 'sem status') + ']'),
    };
  }

  return {
    confirmado: identidades[chaves[0]].some((l) => contratoAssinadoNaPlanilha(l.status)),
    criterio: 'nome',
    candidatos: identidades[chaves[0]].map((l) => l.nomeColaborador || l.razaoSocial),
  };
}

// Lido uma vez, da fonte — e nao de dentro de cada item, que era o que inflava o
// payload em duas ordens de grandeza (ver comentario no node de parse).
const contratosPorProjeto = $('Parsear planilhas (exceljs) e separar AREP/Reunion por cor')
  .first().json.contratosPorProjeto || {};

return $input.all().map((item) => {
  const d = item.json;
  const r = cruzarComPlanilhaContratos(d.nota, d.nomeColaborador, contratosPorProjeto[d.nota.projetoId]);
  return { json: {
    ...d,
    fonteChecagem: 'planilha_contratos',
    confirmado: r.confirmado,
    // spec 3.1: match na planilha preenche a coluna N como "OK - ASSINADO"
    atualizarColunaNPara: r.confirmado ? 'OK - ASSINADO' : undefined,
    // usados pelo alerta de SOLICITAR pendente quando nada confirma
    criterioContrato: r.criterio,
    candidatosContrato: r.candidatos,
  } };
});

// Junta as duas checagens paralelas (spec 3.1): a PRIMEIRA confirmação positiva libera,
// sem prioridade entre as fontes. Como as duas chegam pelo mesmo Merge, "primeira" aqui é
// "qualquer uma que tenha confirmado" — o resultado é o mesmo, e não depende de qual
// terminou antes.
//
// Cada linha pode aparecer até 2x no input (uma por checagem); o agrupamento é por
// chaveLinha. Linhas já resolvidas pela coluna N vêm por outro ramo e passam direto.

const porLinha = new Map();

for (const item of $input.all()) {
  const d = item.json;
  const chave = d.chaveLinha;
  if (chave === null || chave === undefined) continue;

  if (!porLinha.has(chave)) {
    porLinha.set(chave, { base: d, liberado: false, motivo: undefined, valorColunaN: undefined, passaDireto: false });
  }
  const acc = porLinha.get(chave);

  // monitoramento e linhas liberadas pela coluna N não passam pelas checagens paralelas
  if (d.contratoResolvido) {
    acc.base = d;
    acc.passaDireto = true;
    continue;
  }
  acc.base = { ...acc.base, ...d };
  if (d.confirmado && !acc.liberado) {
    acc.liberado = true;
    acc.motivo = d.fonteChecagem;
    acc.valorColunaN = d.atualizarColunaNPara;
  }
}

return [...porLinha.values()].map(({ base, liberado, motivo, valorColunaN, passaDireto }) => {
  if (passaDireto) return { json: base };
  const json = { ...base, liberado, motivoLiberacao: motivo, atualizarColunaNPara: valorColunaN };
  delete json.confirmado;
  delete json.fonteChecagem;
  // criterioContrato/candidatosContrato sobrevivem de proposito: o alerta de SOLICITAR
  // pendente usa isso pra dizer POR QUE nao liberou (ambiguidade, sem candidato...).
  if (liberado) { delete json.criterioContrato; delete json.candidatosContrato; }
  return { json };
});

// Serializa o cobrancas.json atualizado em binário: o node de escrita em disco só aceita
// binário, não JSON. Mesmo padrão do "Preparar log_diario.json atualizado".
//
// Node separado de propósito, em vez de emitir o binário lá no "Consolidar": aquele node
// alimenta 4 ramos, e pendurar o arquivo serializado no item faria os 4 carregarem uma
// cópia — a mesma duplicação de payload que travou a VM.
const cobrancas = $input.first().json.cobrancasAtualizadas || {};
return [{
  json: {},
  binary: { data: {
    data: Buffer.from(JSON.stringify(cobrancas, null, 2)).toString('base64'),
    mimeType: 'application/json',
    fileName: 'cobrancas__SUFIXO_AMBIENTE__.json',
  } },
}];

// Âncora de correlação pra chamada da IA. O node HTTP substitui o json do item pela
// resposta da API, então o contexto da linha (nota, perfil, config, apelidos, liberado...)
// precisa ser recuperado depois — e pra isso é preciso um node estável pra casar via
// pairedItem. Não transforma nada, só passa adiante.
return $input.all();

// Junta as mudancas de planilha dos itens JA montados (o e-mail so foi montado em
// memoria ate aqui — nada foi criado no Gmail ainda). Roda antes do "Switch — ação"
// justamente pra que a gravacao aconteca ANTES da criacao do e-mail: se a escrita
// falhar, a execucao para aqui e nenhum rascunho e criado.
//
// A regra (secao 3.1): e-mail so pode existir com contrato confirmado E coluna N
// efetivamente gravada. Antes, a gravacao rodava no fim do fluxo — os e-mails ja
// existiam quando ela falhava.
const itens = $input.all().map((i) => i.json);

const mudancasColunaN = [];
const mudancasColunaL = [];
for (const d of itens) {
  if (Array.isArray(d.linhasAfetadas)) {
    for (const la of d.linhasAfetadas) {
      if (la.atualizarColunaNPara) mudancasColunaN.push({ projetoId: la.projetoId, linha: la.linha, valor: la.atualizarColunaNPara });
      if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: la.projetoId, linha: la.linha, valor: d.novoValorColunaL });
    }
    continue;
  }
  if (!d.nota) continue;
  if (d.atualizarColunaNPara) mudancasColunaN.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.atualizarColunaNPara });
  if (d.atualizarColunaL && d.novoValorColunaL) mudancasColunaL.push({ projetoId: d.nota.projetoId, linha: d.nota.linha, valor: d.novoValorColunaL });
}

// A coluna L NÃO vai junto: ela só pode ser escrita depois do envio confirmado
// (spec 3.1.5). Quem cuida dela é a cadeia "...(coluna L)", lá no fim do fluxo.
return [{ json: { mudancasColunaN, mudancasColunaL: [] } }];

// So chega aqui se a gravacao da planilha subiu (ou se nao havia nada a gravar).
// Reemite os itens montados, que seguem pro Switch e dai pro Gmail.
return $('Merge — rotas (cobrança/colaborador/fornecedor)').all();

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 0 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(0).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 1 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(1).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 3 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(3).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// A resposta do Gmail substitui o json do item pelos ids do rascunho/mensagem, levando
// embora o payload do pedido (marcadores, acao, chaveCobranca...). Aqui os dois sao casados.
//
// O pareamento e por indice contra a SAIDA 4 do Switch — e nao contra
// $('Merge — rotas...').all()[i]. O Switch DIVIDE os itens entre as saidas, entao o indice
// desta ramificacao nao corresponde ao indice no Merge: com um mix de acoes na mesma
// execucao, a correlacao antiga devolvia o payload de OUTRA linha.
const pedidos = $('Switch — ação').all(4).map((i) => i.json);

return $input.all().map((item, i) => {
  const j = item.json || {};
  const msg = j.message || {};
  return { json: {
    ...(pedidos[i] || {}),
    draftId: j.id || null,
    messageId: msg.id || j.id || null,
    threadIdGmail: msg.threadId || j.threadId || null,
  } };
});

// Segunda escrita da planilha: SÓ a coluna L (Status Box), e SÓ aqui — depois do envio.
//
// Este node fica pendurado em "Consolidar mudanças e cobrancas.json", que só roda depois
// dos nodes de envio do Gmail. Chegar aqui já significa que o e-mail saiu: se o envio
// falhasse, a execução teria parado antes e a coluna L não seria tocada (spec 3.1.5).
//
// Em MODO_EXECUCAO=rascunho a lista vem vazia (atualizarColunaL é false), então o IF
// seguinte corta o caminho e nada é gravado.
const d = $input.first().json;
return [{ json: { mudancasColunaN: [], mudancasColunaL: d.mudancasColunaL || [] } }];

// Alerta de "SOLICITAR pendente de contrato" (spec 3.1). Uma mensagem por execução,
// agrupando todas as linhas — no estilo do relatório final, e não uma mensagem por linha.
//
// Só entra SOLICITAR (qualquer variante/escala da 3.1.4). "PROGRAMAR ATÉ" tem prazo e fica
// de fora de propósito.
function formatarValor(v) {
  const n = Number(v);
  return isFinite(n) ? n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : String(v || '?');
}
function formatarData(d) {
  const dt = new Date(d);
  return isNaN(dt.getTime()) ? String(d || '?') : dt.toLocaleDateString('pt-BR', { timeZone: 'UTC' });
}

const itens = $('Merge — resultados consolidados').all().map((i) => i.json);
const pendentes = itens.filter((d) => d.acao === 'pendente_contrato' && d.gatilho === 'SOLICITAR');

const linhas = pendentes.map((d) => {
  const n = d.nota || {};
  const quem = d.nomeColaborador || n.colunaH || '?';
  const urgente = d.escalaUrgencia === 0 ? ' 🔴 URG' : '';
  // Quando a planilha de Contratos achou mais de uma pessoa possivel, o alerta precisa
  // dizer QUAIS — e a Michelle que decide, e sem os nomes ela nao tem como (spec 3.1).
  const motivo = d.criterioContrato === 'ambiguidade'
    ? '\n   ⚠️ ambíguo na planilha de Contratos — mais de um candidato:\n' +
      (d.candidatosContrato || []).map((x) => '      · ' + x).join('\n')
    : '';
  return '• ' + (n.projetoId || '?') + ' L' + (n.linha || '?') + urgente + '\n' +
    '   ' + quem + '\n' +
    '   R$ ' + formatarValor(n.colunaK) + ' · venc. ' + formatarData(n.colunaG) + ' · Status Box: "' + (n.colunaL || '') + '"' + motivo;
});

const texto = [
  '⚠️ SOLICITAR pendente de contrato — nenhum e-mail foi enviado',
  '',
  pendentes.length + ' linha(s) com Status Box "SOLICITAR" não tiveram o contrato confirmado',
  'nesta execução: nem a planilha de Contratos nem a ficha cadastral no Gmail liberaram.',
  '',
].concat(linhas).concat([
  '',
  'Como "SOLICITAR" é pedido urgente, essas linhas precisam de ação manual — elas',
  'continuam paradas até o contrato ser confirmado.',
]).join('\n');

return [{ json: { quantidade: pendentes.length, textoAlerta: texto } }];

// Checagem do rascunho na data-alvo (spec 3.1.8). O GET devolve 200 se o rascunho ainda
// existe e 404 se sumiu — a Michelle enviou manualmente antes da automacao agir, que e
// caminho normal, nao erro.
const pedidos = $('Switch — ação').all(2).map((i) => i.json);
return $input.all().map((item, i) => {
  const resp = item.json || {};
  const existe = resp.statusCode >= 200 && resp.statusCode < 300;
  return { json: { ...(pedidos[i] || {}), rascunhoExiste: existe, httpChecagem: resp.statusCode } };
});

// Envio do rascunho programado confirmado. So AQUI a coluna L pode virar "SOLICITADA MI"
// (spec 3.1.5 + 3.1.8): antes disso nao havia envio nenhum.
const pedidos = $('Decidir envio do rascunho programado').all().map((i) => i.json).filter((d) => d.rascunhoExiste);
return $input.all().map((item, i) => {
  const d = pedidos[i] || {};
  const j = item.json || {};
  const corpo = j.body || j;
  const enviou = j.statusCode === undefined || (j.statusCode >= 200 && j.statusCode < 300);
  if (!enviou) {
    // falhou o envio: NAO grava coluna L. O Error Handler ja alerta pelo status.
    throw new Error('falha ao enviar o rascunho programado (HTTP ' + j.statusCode + '): ' + JSON.stringify(corpo).slice(0, 200));
  }
  return { json: {
    ...d,
    acao: 'programado_enviado',
    threadIdGmail: (corpo && corpo.threadId) || d.threadIdGmail || null,
    atualizarColunaL: true,
    novoValorColunaL: 'SOLICITADA MI',
    linhasAfetadas: (d.linhasAfetadas || []).map((la) => ({ ...la })),
  } };
});

function statusBoxAindaAntesDoEnvio(statusBox) {
  const s = String(statusBox || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();
  return /^PROGRAMAR ATE/.test(s) || /^SOLICITAR/.test(s);
}

// Rascunho nao existe mais: a Michelle enviou manualmente. NAO reenviar (spec 3.1.8) —
// reenviar duplicaria o pedido pro colaborador.
//
// So grava coluna L se o Status Box AINDA estiver num estagio anterior ao envio. Se ja
// avancou (ENTREGUE MI, ENTREGUE MI R1...), a automacao nao pode regredir o que foi feito
// a mao. O valor usado e o colunaL lido nesta execucao, direto do Cost Report.
return $input.all().map((item) => {
  const d = item.json;
  const statusAtual = (d.nota && d.nota.colunaL) || '';
  const podeGravar = statusBoxAindaAntesDoEnvio(statusAtual);
  return { json: {
    ...d,
    acao: 'programado_ja_enviado_manualmente',
    atualizarColunaL: podeGravar,
    novoValorColunaL: podeGravar ? 'SOLICITADA MI' : undefined,
    // registro auditavel — entra no resumo/log, sem alerta urgente (3.1.8)
    auditoria: podeGravar
      ? 'rascunho programado ausente (enviado manualmente); Status Box ainda era "' + statusAtual + '", atualizado para SOLICITADA MI'
      : 'rascunho programado ausente (enviado manualmente); Status Box ja estava em "' + statusAtual + '" — nao regredido',
  } };
});

// Corta as linhas que NAO sao da fonte desta passada (spec.md 3.1.5, 09/09).
//
// O ciclo completo — leitura, checagem de contrato, escrita e as duas camadas de
// confirmacao — tem que rodar por inteiro para UMA fonte antes da proxima. Sem isso, a
// Camada 2 conferia a lista de mudancas das DUAS fontes contra um unico arquivo aberto:
// na melhor hipotese abortava por divergencia espuria, na pior dava FALSO POSITIVO,
// porque os numeros de linha se repetem entre as planilhas (a celula N293 existe nas duas).
//
// O corte e por ARQUIVO, nao por projeto: AREP e REUNION vivem na MESMA planilha (S01,
// distinguidos pela cor da linha — secao 6), entao os dois entram na mesma passada e
// escrevem no mesmo arquivo. Isso e correto: uma passada, um arquivo, uma conferencia.
