// ETAPA 1 do spec 3.1 (redesenho de 11/09) — RESTRINGE candidatos, NUNCA confirma.
//
// O bug que isto corrige: a versao anterior buscava o nome em qualquer lugar da mensagem, e
// o Gmail casa termo solto em qualquer campo — inclusive no CC. Como a Coordenadora Executiva
// fica em copia em quase toda thread de contratacao, a linha dela casava com 104 mensagens de
// OUTRAS pessoas (caso real "Vanessa Paes", execucao 214).
//
// Criterios de plausibilidade (spec 3.1):
//   (a) a mensagem foi endereçada ao e-mail do colaborador (coluna R da planilha Cost), OU
//   (b) o nome do colaborador OU a razao social aparece no ASSUNTO ou no CORPO NOVO.
// NUNCA no CC, NUNCA no corpo citado (thread anterior) — que era exatamente a origem do falso
// positivo. Passar aqui nao libera nada: quem confirma e a Etapa 2, lendo a ficha.

function normalizar(texto) {
  if (!texto) return '';
  return String(texto).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim().replace(/\s+/g, ' ');
}

function indiceDeOrigem(item) {
  const p = item.pairedItem;
  if (p === undefined || p === null) return null;
  if (typeof p === 'number') return p;
  if (Array.isArray(p)) return p.length && p[0] ? p[0].item : null;
  return p.item === undefined ? null : p.item;
}

// Corta o corpo citado. Sem isto, o nome que aparece na assinatura de uma thread antiga
// encaminhada valeria como "corpo novo" — e voltariamos ao falso positivo por outro caminho.
function corpoNovo(texto) {
  const linhas = String(texto || '').split(/\r?\n/);
  const MARCA = /^\s*(>|Em .*escreveu:|On .*wrote:|-{2,}\s*Mensagem encaminhada|De:\s|From:\s|Enviada em:\s)/i;
  const novo = [];
  for (const l of linhas) {
    if (MARCA.test(l)) break;
    novo.push(l);
  }
  return novo.join('\n');
}

// "o nome aparece no texto": exige o PRIMEIRO e o ULTIMO token do nome, na mesma tolerancia
// ja usada na checagem de Contratos. Substring do nome inteiro seria estrito demais (some com
// nome do meio diferente); token solto seria frouxo demais (um "SANTOS" casaria com qualquer um).
function nomeApareceEm(texto, nome) {
  const alvo = normalizar(texto);
  const tokens = normalizar(String(nome || '').replace(/^[\d.\-/\s]+/, '')).split(' ').filter(Boolean);
  if (!alvo || tokens.length === 0) return false;
  if (tokens.length === 1) return alvo.includes(tokens[0]);
  return alvo.includes(tokens[0]) && alvo.includes(tokens[tokens.length - 1]);
}

function textoDe(campo) {
  if (!campo) return '';
  if (typeof campo === 'string') return campo;
  try { return JSON.stringify(campo); } catch (e) { return ''; }
}

const origem = $('Preparar checagem paralela de contrato').all().map((i) => i.json);
const entradas = $input.all();
const saida = [];

for (let k = 0; k < entradas.length; k++) {
  const item = entradas[k];
  const i = indiceDeOrigem(item);
  if (i === null || !origem[i]) continue;
  const linha = origem[i];
  const msg = item.json || {};

  const assunto = msg.subject || '';
  const novo = corpoNovo(msg.text || '');
  const alvos = [linha.nomeColaborador, linha.nota && linha.nota.colunaH].filter(
    (v) => v && !/FALTA INFORMA/i.test(String(v)),
  );

  // (b) nome ou razao social no assunto ou no corpo novo
  const casouTexto = alvos.some((a) => nomeApareceEm(assunto, a) || nomeApareceEm(novo, a));

  // (a) endereçada ao e-mail da coluna R — so o campo TO, nunca o CC
  const emailR = normalizar(linha.nota && linha.nota.colunaR);
  const para = normalizar(textoDe(msg.to));
  const casouEmail = !!emailR && emailR.includes('@') && para.includes(emailR);

  if (!casouTexto && !casouEmail) continue;

  saida.push({
    json: {
      messageId: msg.id,
      chaveLinha: linha.chaveLinha,
      indiceOrigem: i,
      motivo: casouEmail ? 'email_coluna_R' : 'nome_no_assunto_ou_corpo_novo',
      assunto: String(assunto).slice(0, 120),
    },
    pairedItem: { item: k },
  });
}

